/* Ngữ pháp C1 · Advanced — sinh tự động bởi tools/build-grammar.py (npm run build:grammar), đừng sửa tay */
(window.FA_GRAMMAR_LESSONS = window.FA_GRAMMAR_LESSONS || {})["C1"] = [{"n":1,"title":"Past perfect continuous","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Thì này đặt một quá trình kéo dài ở phía trước một mốc quá khứ và thường nêu rõ thời lượng của quá trình đó. So với quá khứ hoàn thành, nó quan tâm đến việc đã diễn ra bao lâu hơn là việc đã hoàn tất bao nhiêu. Thì này cũng dùng để giải thích nguyên nhân của một tình trạng được quan sát trong quá khứ."},{"p":"Cấu trúc chính: had been + V-ing"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She had been waiting for two hours when the train finally arrived. (Nhấn mạnh thời lượng trước mốc quá khứ | Nguyên nhân của một tình trạng quá khứ | Việc lặp lại liên tục trước một mốc)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nhấn mạnh thời lượng trước mốc quá khứ: Thường đi với for, since, all day, all morning. (He had been studying for six hours when I called.)"},{"p":"Nguyên nhân của một tình trạng quá khứ: Quá trình trước đó để lại dấu vết nhìn thấy được tại mốc tham chiếu. (Her eyes were red because she had been crying.)"},{"p":"Việc lặp lại liên tục trước một mốc: Nhấn mạnh tính liên tục của chuỗi hành động. (They had been calling all week before he replied.)"},{"p":"Trong câu tường thuật: Hiện tại hoàn thành tiếp diễn khi lùi thì trở thành quá khứ hoàn thành tiếp diễn. (He said he had been working since dawn.)"},{"p":"Ghi nhớ: Nhấn mạnh quá trình kéo dài trước một mốc trong quá khứ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: had been + V-ing"},{"table":[["Nhóm cấu trúc","Công thức / Quy tắc","Ví dụ"],["Khẳng định","S + had been + V-ing (dùng chung cho mọi chủ ngữ)","They had been arguing."],["Phủ định","had not (hadn't) been + V-ing","She hadn't been sleeping well."],["Nghi vấn","Had + S + been + V-ing?","How long had you been waiting?"],["Động từ không dùng","know, own, belong - dùng quá khứ hoàn thành thay thế","I had known her for years."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mốc tham chiếu trong quá khứ: Mốc này thường là một mệnh đề ở quá khứ đơn. (when the train arrived)"},{"p":"02. Đưa quá trình vào had been cộng V-ing: Cấu trúc gồm ba phần cố định, chỉ động từ chính đổi. (had been waiting)"},{"p":"03. Nêu thời lượng bằng for hoặc since: Thời lượng là thông tin đặc trưng của thì này, nếu thiếu thì quá khứ hoàn thành thường đủ dùng. (for two hours)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Nhấn mạnh thời lượng","She had been waiting for two hours when the train finally arrived.\n(Cô ấy đã đợi hai tiếng thì tàu mới tới.)","Quá trình đợi kéo dài trước mốc tàu tới; for two hours là thông tin đặc trưng của thì này."],["Giải thích tình trạng","Her eyes were red because she had been crying.\n(Mắt cô ấy đỏ vì đã khóc.)","Quá trình khóc xảy ra trước và để lại dấu vết tại mốc tham chiếu ở quá khứ đơn."],["Với since","He had been working at the company since 2015 when it closed.\n(Anh ấy làm ở công ty đó từ năm 2015 cho đến khi công ty đóng cửa.)","Since đánh dấu điểm bắt đầu của quá trình, mốc kết thúc là mệnh đề quá khứ đơn."],["Việc lặp lại","They had been calling him all week before he finally replied.\n(Họ gọi cho anh ấy suốt tuần thì anh ấy mới trả lời.)","All week cho thấy chuỗi hành động lặp lại liên tục trước mốc."],["Phủ định","She hadn't been sleeping well, which explained her exhaustion.\n(Cô ấy đã ngủ không ngon, điều đó giải thích vì sao cô kiệt sức.)","Not đặt giữa had và been."],["Trong câu tường thuật","He said he had been working since dawn.\n(Anh ấy nói đã làm việc từ sáng sớm.)","Hiện tại hoàn thành tiếp diễn khi lùi thì trở thành quá khứ hoàn thành tiếp diễn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai thì quá khứ hoàn thành"},{"table":[["Thì / Cấu trúc","Trọng tâm","Ví dụ"],["had + V3","nhấn mạnh việc đã hoàn tất trước mốc","She had written three emails."],["had been + V-ing","nhấn mạnh quá trình và thời lượng trước mốc","She had been writing emails all morning."],["quá khứ tiếp diễn","đang diễn ra đúng tại mốc, không nhấn thời lượng trước đó","She was writing when I came in."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She was waiting for two hours when the train arrived. → Đã sửa: She had been waiting for two hours when the train arrived. — Quá trình kéo dài trước một mốc quá khứ cần quá khứ hoàn thành tiếp diễn."},{"p":"Chưa đúng: She had waiting for two hours. → Đã sửa: She had been waiting for two hours. — Thiếu been thì cấu trúc chưa hoàn chỉnh."},{"p":"Chưa đúng: I had been knowing her for years before we worked together. → Đã sửa: I had known her for years before we worked together. — Know là động từ chỉ trạng thái nên dùng quá khứ hoàn thành."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Cấu trúc có đủ had, been và V-ing."},{"p":"Mốc tham chiếu quá khứ đã được nêu rõ."},{"p":"Thời lượng được nêu bằng for hoặc since."},{"p":"Động từ không thuộc nhóm chỉ trạng thái."}]}],"id":"c1-01"},{"n":2,"title":"Future perfect","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Tương lai hoàn thành nhìn từ một điểm trong tương lai về phía trước đó: tại mốc ấy, việc đã xong. Dấu hiệu đặc trưng là cụm by cộng mốc thời gian hoặc mệnh đề thời gian. Thì này cũng dùng để suy đoán rằng một việc hẳn đã hoàn tất vào lúc này."},{"p":"Cấu trúc chính: will have + V3"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): By next June I will have finished my thesis. (Việc hoàn tất trước mốc tương lai | Nêu tổng kết tính đến một mốc tương lai | Suy đoán về việc hẳn đã xong)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Việc hoàn tất trước mốc tương lai: Thường đi với by, by the time, before. (By Friday they will have completed the audit.)"},{"p":"Nêu tổng kết tính đến một mốc tương lai: Dùng khi đếm thời lượng hoặc số lần tính đến mốc đó. (Next month she will have worked here for ten years.)"},{"p":"Suy đoán về việc hẳn đã xong: Người nói tin rằng việc đã hoàn tất dù không chứng kiến. (They will have landed by now.)"},{"p":"Trong văn bản kế hoạch và dự báo: Thường gặp ở báo cáo, lộ trình và dự báo kinh tế. (By 2030 the city will have doubled in size.)"},{"p":"Ghi nhớ: Diễn tả việc sẽ hoàn tất trước một mốc trong tương lai."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: will have + V3"},{"table":[["Nhóm cấu trúc","Công thức / Quy tắc","Ví dụ"],["Khẳng định","S + will have + V3","He will have left."],["Phủ định","won't have + V3","They won't have finished."],["Nghi vấn","Will + S + have + V3?","Will you have arrived by six?"],["Mệnh đề thời gian","by the time + hiện tại đơn","By the time you read this, I will have gone."],["V3 bất quy tắc","write → written, leave → left, do → done","By the end of the week he will have written the report."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mốc tương lai làm điểm nhìn: Mốc này thường được nêu bằng by cộng thời gian hoặc by the time cộng mệnh đề. (by next June)"},{"p":"02. Dùng will have cộng quá khứ phân từ: Will không chia theo chủ ngữ và have giữ nguyên dạng nguyên mẫu. (will have finished)"},{"p":"03. Dùng hiện tại đơn trong mệnh đề thời gian: Sau by the time, when, before thì không dùng will. (By the time he arrives, …)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Hoàn tất trước mốc","By next June I will have finished my thesis.\n(Đến tháng Sáu tới, tôi sẽ viết xong luận văn.)","Mốc tháng Sáu là điểm nhìn; tại thời điểm đó việc đã hoàn tất."],["Mệnh đề thời gian","By the time you read this letter, I will have left the country.\n(Khi bạn đọc thư này thì tôi đã rời khỏi nước.)","Mệnh đề sau by the time dùng hiện tại đơn, mệnh đề chính dùng tương lai hoàn thành."],["Tổng kết thời lượng","Next month she will have worked here for ten years.\n(Tháng sau, cô ấy đã làm ở đây được mười năm.)","Thì này dùng để đếm thời lượng tính đến một mốc tương lai."],["Suy đoán","Their flight left at six, so they will have landed by now.\n(Chuyến bay của họ khởi hành lúc sáu giờ nên giờ hẳn đã hạ cánh.)","By now cho thấy người nói suy đoán việc đã hoàn tất ở hiện tại."],["Phủ định","I'm afraid we won't have received the results by Monday.\n(Tôi e là đến thứ Hai chúng ta vẫn chưa nhận được kết quả.)","Phủ định là won't have cộng quá khứ phân từ."],["Dự báo","By 2030 the population will have doubled.\n(Đến năm 2030 dân số sẽ tăng gấp đôi.)","Thì này rất hay gặp trong báo cáo và dự báo."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba cách nhìn về tương lai"},{"table":[["Cấu trúc","Ý nghĩa tại mốc","Ví dụ"],["will + V","sự việc xảy ra tại mốc đó","At six I will leave."],["will be + V-ing","đang diễn ra tại mốc đó","At six I will be leaving."],["will have + V3","đã hoàn tất trước mốc đó","By six I will have left."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: By next June I will finish my thesis already. → Đã sửa: By next June I will have finished my thesis. — Việc hoàn tất trước một mốc tương lai cần will have cộng quá khứ phân từ."},{"p":"Chưa đúng: By the time he will arrive, we will have left. → Đã sửa: By the time he arrives, we will have left. — Mệnh đề thời gian không dùng will."},{"p":"Chưa đúng: They will have went by then. → Đã sửa: They will have gone by then. — Sau have phải là quá khứ phân từ gone."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Mốc tương lai làm điểm nhìn đã được nêu rõ."},{"p":"Cấu trúc có đủ will have cộng quá khứ phân từ."},{"p":"Mệnh đề thời gian dùng hiện tại đơn."},{"p":"Cụm by hoặc by the time xuất hiện khi cần làm rõ mốc."}]}],"id":"c1-02"},{"n":3,"title":"Future perfect continuous","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Thì này đo thời lượng của một quá trình tính tới một mốc tương lai, trả lời câu hỏi đến lúc đó đã làm việc này bao lâu. Nó khác tương lai hoàn thành ở chỗ không nhấn mạnh việc hoàn tất mà nhấn mạnh quá trình còn đang tiếp diễn. Cấu trúc gồm bốn thành phần cố định và luôn đi với cụm chỉ thời lượng."},{"p":"Cấu trúc chính: will have been + V-ing"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): By December she will have been teaching here for twenty years. (Đo thời lượng tính đến mốc tương lai | Nhấn mạnh quá trình còn tiếp tục | Tình trạng dự đoán ở mốc tương lai)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Đo thời lượng tính đến mốc tương lai: Thường đi với for + khoảng thời gian, nhưng cũng có thể dùng cách biểu đạt thời lượng khác như since + mốc bắt đầu, all day hoặc câu hỏi How long…?. (By May I will have been working here for five years. / By June, I will have been working here since January.)"},{"p":"Nhấn mạnh quá trình còn tiếp tục: Quá trình chưa kết thúc tại mốc được nói tới. (By then they will have been building the bridge for a decade.)"},{"p":"Tình trạng dự đoán ở mốc tương lai: Dùng khi muốn nói lí do của một trạng thái sẽ xảy ra. (He will be tired - he will have been driving all day.)"},{"p":"Trong báo cáo dự án dài hạn: Thường gặp khi tổng kết tiến độ theo thời gian. (By the final review we will have been collecting data for two years.)"},{"p":"Ghi nhớ: Nêu thời lượng của một quá trình tính đến một mốc trong tương lai."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: will have been + V-ing"},{"table":[["Nhóm cấu trúc","Công thức / Quy tắc","Ví dụ"],["Khẳng định","S + will have been + V-ing","She will have been waiting."],["Phủ định","won't have been + V-ing","They won't have been working long."],["Nghi vấn","Will + S + have been + V-ing?","How long will you have been studying?"],["Động từ không dùng","động từ chỉ trạng thái - dùng tương lai hoàn thành thay thế","By then I will have known her for a decade."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mốc tương lai và thời lượng: Mốc nêu bằng by, thời lượng nêu bằng for. (by December /for twenty years)"},{"p":"02. Giữ đủ will have been cộng V-ing: Thiếu been là lỗi thường gặp nhất của thì này. (will have been teaching)"},{"p":"03. Xét trọng tâm: thời lượng hay hoàn tất: Nếu trọng tâm là việc đã xong thì dùng tương lai hoàn thành. (will have finished ↔ will have been working)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Đo thời lượng","By December she will have been teaching here for twenty years.\n(Đến tháng Mười hai, cô ấy đã dạy ở đây được hai mươi năm.)","Mốc by December kết hợp với thời lượng for twenty years là cặp dấu hiệu đặc trưng."],["Quá trình còn tiếp tục","By next spring they will have been building the bridge for a decade.\n(Đến mùa xuân tới, họ đã xây cây cầu đó được mười năm.)","Việc xây chưa xong tại mốc đó, nên thì tiếp diễn phù hợp hơn."],["Giải thích tình trạng dự đoán","He will be exhausted when he arrives\n- he will have been driving for ten hours.\n(Anh ấy sẽ kiệt sức khi tới, vì lúc đó đã lái xe mười tiếng.)","Quá trình lái xe giải thích cho tình trạng kiệt sức ở mốc tương lai."],["Báo cáo dự án","By the final review we will have been collecting data for two years.\n(Đến buổi đánh giá cuối là chúng tôi thu thập dữ liệu được hai năm.)","Thì này rất hay dùng để tổng kết tiến độ theo thời gian."],["Nghi vấn","How long will you have been living abroad by the time you return?\n(Đến lúc về thì bạn sống ở nước ngoài bao lâu rồi?)","Câu hỏi với how long là mẫu đặc trưng vì thì này đo thời lượng."],["Động từ chỉ trạng thái","By then I will have known her for a decade.\n(Đến lúc đó, tôi đã biết cô ấy được mười năm.)","Know chỉ trạng thái nên dùng tương lai hoàn thành; dạng tiếp diễn không dùng được với động từ này."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai thì hoàn thành ở tương lai"},{"table":[["Cấu trúc","Trọng tâm","Ví dụ"],["will have + V3","việc đã xong trước mốc","By May I will have finished the course."],["will have been + V-ing","quá trình kéo dài bao lâu tính đến mốc","By May I will have been studying for a year."],["will be + V-ing","đang diễn ra đúng tại mốc","In May I will be studying for the finals."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: By December she will have teaching here for twenty years. → Đã sửa: By December she will have been teaching here for twenty years. — Thiếu been thì cấu trúc chưa hoàn chỉnh."},{"p":"Chưa đúng: By December she will be teaching here for twenty years. → Đã sửa: By December she will have been teaching here for twenty years. — Tương lai tiếp diễn không đo được thời lượng tính đến một mốc."},{"p":"Chưa đúng: By then I will have been knowing her for a decade. → Đã sửa: By then I will have known her for a decade. — Know là động từ chỉ trạng thái nên không dùng dạng tiếp diễn."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Cấu trúc có đủ will have been cộng V-ing."},{"p":"Mốc tương lai và thời lượng đều được nêu."},{"p":"Trọng tâm là thời lượng chứ không phải sự hoàn tất."},{"p":"Động từ không thuộc nhóm chỉ trạng thái."}]}],"id":"c1-03"},{"n":4,"title":"Past modals","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Khi ghép động từ khuyết thiếu với have cộng quá khứ phân từ, người nói chuyển sắc thái của mình về quá khứ: suy đoán về điều đã xảy ra, phê bình điều lẽ ra nên làm hoặc tiếc về cơ hội đã bỏ qua. Mỗi động từ khuyết thiếu giữ nguyên sắc thái vốn có của nó, chỉ mốc thời gian là đổi."},{"p":"Cấu trúc chính: must/should/could/might/needn't + have + V3"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): You should have told me earlier. (Suy đoán về quá khứ | Phê bình hoặc tiếc nuối | Nêu cơ hội đã bỏ qua)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Suy đoán về quá khứ: Must have là kết luận gần như chắc chắn, can't have là loại trừ, may hoặc might have là khả năng. (She must have forgotten. / He can't have seen us.)"},{"p":"Phê bình hoặc tiếc nuối: Should have và ought to have nêu điều lẽ ra nên làm nhưng đã không làm. (You should have told me.)"},{"p":"Nêu cơ hội đã bỏ qua: Could have chỉ việc có khả năng làm được nhưng đã không làm. (We could have taken the earlier train.)"},{"p":"Nêu việc không cần thiết đã làm: Needn't have cho biết việc đã làm nhưng thực ra không cần. (You needn't have cooked - we ate on the way.)"},{"p":"Ghi nhớ: Dùng để suy đoán, phê bình hoặc tiếc nuối về một việc trong quá khứ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: must/should/could/might/needn't + have + V3"},{"table":[["Sắc thái","Công thức","Ví dụ"],["Suy đoán","must / can't / may / might + have + V3","They must have left early."],["Phê bình","should (not) / ought (not) to + have + V3","You shouldn't have shouted."],["Cơ hội bỏ qua","could + have + V3","She could have won."],["Không cần thiết","needn't + have + V3","He needn't have worried."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Giữ nguyên dạng động từ khuyết thiếu: Động từ khuyết thiếu không chia theo chủ ngữ và không có dạng quá khứ riêng ở đây. (She must have…, không phải She musted have…)"},{"p":"02. Thêm have rồi quá khứ phân từ: Have giữ nguyên dạng, không đổi thành has hay had. (must have gone)"},{"p":"03. Chọn động từ khuyết thiếu theo sắc thái: Suy đoán, phê bình, tiếc nuối hay không cần thiết đều có cấu trúc riêng. (should have ↔ needn't have)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Phê bình","You should have told me earlier.\n(Đáng ra bạn nên nói với tôi sớm hơn.)","Thực tế là việc đó đã không xảy ra; cấu trúc này hàm ý phê bình nhẹ."],["Suy đoán chắc chắn","The lights are off, so they must have gone to bed.\n(Đèn tắt hết rồi nên chắc họ đã đi ngủ.)","Must have là kết luận gần như chắc chắn về một việc trong quá khứ."],["Loại trừ","He can't have seen us - he was looking the other way.\n(Anh ấy không thể thấy chúng ta, lúc đó anh ấy nhìn hướng khác.)","Can't have là dạng phủ định của suy đoán must have."],["Khả năng","She might have missed the train.\n(Có thể cô ấy đã không kịp chuyến tàu.)","Might have và may have đều chỉ một khả năng trong quá khứ."],["Cơ hội bỏ qua","We could have taken the earlier train, but we didn't check the timetable.\n(Chúng ta có thể bắt chuyến tàu sớm hơn nhưng đã không xem giờ.)","Could have chỉ khả năng đã có nhưng không thực hiện."],["Không cần thiết","You needn't have cooked - we had already eaten.\n(Bạn không cần nấu đâu, chúng tôi ăn rồi.)","Needn't have cho biết việc đã làm rồi nhưng thực ra không cần."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Bốn sắc thái về quá khứ"},{"table":[["Cấu trúc","Nghĩa","Ví dụ"],["must have + V3","gần như chắc chắn đã xảy ra","He must have left."],["can't have + V3","gần như chắc chắn không xảy ra","He can't have left."],["should have + V3","lẽ ra nên làm nhưng đã không làm","He should have left."],["needn't have + V3","đã làm nhưng không cần","He needn't have left."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: You should told me earlier. → Đã sửa: You should have told me earlier. — Thiếu have thì câu chỉ còn là lời khuyên về hiện tại."},{"p":"Chưa đúng: She must has forgotten. → Đã sửa: She must have forgotten. — Have giữ nguyên dạng nguyên mẫu sau động từ khuyết thiếu."},{"p":"Chưa đúng: You didn't need to cook, but you did, so you didn't need have cooked. → Đã sửa: You needn't have cooked. — Didn't need to hàm ý không cần và đã không làm; needn't have hàm ý đã làm nhưng không cần."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Cấu trúc có đủ have cộng quá khứ phân từ."},{"p":"Have giữ nguyên dạng nguyên mẫu."},{"p":"Động từ khuyết thiếu phản ánh đúng sắc thái."},{"p":"Không lẫn needn't have với didn't need to."}]}],"id":"c1-04"},{"n":5,"title":"Mixed conditionals","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Điều kiện hỗn hợp xuất hiện khi điều kiện và kết quả nằm ở hai mốc thời gian khác nhau. Dạng phổ biến nhất là điều kiện trái với quá khứ dẫn tới kết quả trái với hiện tại. Dạng còn lại là điều kiện trái với hiện tại dẫn tới kết quả trái với quá khứ. Cả hai dạng đều lấy mệnh đề if từ một loại điều kiện và mệnh đề chính từ loại khác."},{"p":"Cấu trúc chính: If + had + V3, would + V (hiện tại)"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): If I had studied medicine, I would be a doctor now. (Quá khứ ảnh hưởng đến hiện tại | Hiện tại giải thích cho quá khứ | Hiện tại được giải thích bằng quá khứ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Quá khứ ảnh hưởng đến hiện tại: Mệnh đề if ở quá khứ hoàn thành, mệnh đề chính ở would cộng động từ nguyên mẫu. (If I had saved more, I would have a car now.)"},{"p":"Hiện tại giải thích cho quá khứ: Mệnh đề if ở quá khứ đơn, mệnh đề chính ở would have cộng quá khứ phân từ. (If she weren't so shy, she would have spoken up.)"},{"p":"Hiện tại được giải thích bằng quá khứ: Rất hay dùng để nói về hệ quả lâu dài của một quyết định đã qua. (If we hadn't moved, the children would be at a different school.)"},{"p":"Đặc điểm thường xuyên và một việc đã qua: Mệnh đề if nêu tính cách hoặc hoàn cảnh ổn định. (If he were more careful, he wouldn't have lost the keys.)"},{"p":"Ghi nhớ: Ghép điều kiện ở một mốc thời gian với kết quả ở mốc thời gian khác."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: If + had + V3, would + V (hiện tại)"},{"table":[["Dạng thức","Công thức / Quy tắc","Ví dụ"],["Quá khứ → hiện tại","If + had + V3, would + V nguyên mẫu","If I had taken that job, I would live in Hanoi."],["Hiện tại → quá khứ","If + quá khứ đơn, would have + V3","If I spoke French, I would have applied."],["Dấu hiệu thời gian","now, today, at the moment ở mệnh đề chính của dạng thứ nhất","I would be richer now."],["Động từ khuyết thiếu khác","could, might thay cho would ở cả hai dạng","If I had studied, I could help you now."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mốc thời gian của điều kiện: Điều kiện thuộc quá khứ thì mệnh đề if dùng quá khứ hoàn thành; thuộc hiện tại thì dùng quá khứ đơn. (If I had studied… ↔ If I spoke…)"},{"p":"02. Xác định mốc thời gian của kết quả: Kết quả thuộc hiện tại thì dùng would cộng nguyên mẫu; thuộc quá khứ thì dùng would have cộng quá khứ phân từ. (I would be… ↔ I would have been…)"},{"p":"03. Kiểm tra dấu hiệu thời gian trong câu: Các từ như now, today chỉ hiện tại; last year, yesterday chỉ quá khứ. (I would be a doctor now.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Quá khứ sang hiện tại","If I had studied medicine, I would be a doctor now.\n(Nếu hồi đó tôi học y thì giờ tôi đã là bác sĩ.)","Điều kiện thuộc quá khứ, kết quả thuộc hiện tại, nên từ now là dấu hiệu quyết định."],["Hệ quả lâu dài","If we hadn't moved to Hue, the children would be at a different school.\n(Nếu chúng tôi không chuyển về Huế thì các con đang học trường khác.)","Quyết định quá khứ tạo ra tình trạng hiện tại."],["Hiện tại sang quá khứ","If I spoke French, I would have applied for that position.\n(Nếu tôi biết tiếng Pháp thì tôi đã ứng tuyển vị trí đó.)","Việc không biết tiếng Pháp là tình trạng ổn định ở hiện tại, còn việc ứng tuyển thuộc quá khứ."],["Tính cách ảnh hưởng tới quá khứ","If she weren't so shy, she would have spoken up at the meeting.\n(Nếu cô ấy không rụt rè như vậy thì đã lên tiếng ở cuộc họp.)","Mệnh đề if nêu đặc điểm thường xuyên, mệnh đề chính nói về một việc đã qua."],["Dùng could","If I had learned to drive, I could help you with the move today.\n(Nếu tôi học lái xe thì hôm nay đã giúp bạn chuyển nhà được.)","Could thay would để nhấn mạnh khả năng ở hiện tại."],["Trật tự đảo","She would have more options now if she had finished her degree.\n(Giờ cô ấy sẽ có nhiều lựa chọn hơn nếu đã học xong.)","Mệnh đề if đứng sau nên không cần dấu phẩy, nhưng hai mốc thời gian vẫn khác nhau."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Bốn tổ hợp điều kiện và kết quả"},{"table":[["Loại câu","Tổ hợp thời gian","Ví dụ"],["Loại 2","hiện tại giả định → hiện tại giả định","If I had time, I would help."],["Loại 3","quá khứ trái thực → quá khứ trái thực","If I had had time, I would have helped."],["Hỗn hợp 1","quá khứ trái thực → hiện tại","If I had slept, I wouldn't be tired now."],["Hỗn hợp 2","hiện tại giả định → quá khứ","If I were braver, I would have asked."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: If I had studied medicine, I would have been a doctor now. → Đã sửa: If I had studied medicine, I would be a doctor now. — Từ now chỉ hiện tại nên mệnh đề chính dùng would cộng nguyên mẫu."},{"p":"Chưa đúng: If I would have studied medicine, I would be a doctor now. → Đã sửa: If I had studied medicine, I would be a doctor now. — Mệnh đề if không dùng would."},{"p":"Chưa đúng: If I spoke French, I would apply for that position last year. → Đã sửa: If I spoke French, I would have applied for that position last year. — Kết quả thuộc quá khứ nên mệnh đề chính dùng would have cộng quá khứ phân từ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Mốc thời gian của điều kiện đã được xác định."},{"p":"Mốc thời gian của kết quả đã được xác định."},{"p":"Mệnh đề if không có would."},{"p":"Dấu hiệu thời gian trong câu khớp với dạng động từ đã chọn."}]}],"id":"c1-05"},{"n":6,"title":"Alternatives to if","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Trong văn phong trang trọng và học thuật, người viết thường thay if bằng những cách diễn đạt chính xác hơn về sắc thái. Provided that và on condition that nêu điều kiện bắt buộc. But for cộng danh từ nêu điều kiện phủ định ngắn gọn. Otherwise nêu hệ quả nếu điều kiện không được thoả. Suppose và supposing dùng để nêu giả thiết trong thảo luận."},{"p":"Cấu trúc chính: provided that + mệnh đề | but for + danh từ"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): But for your help, we would have failed. (Nêu điều kiện bắt buộc trong văn bản | Nêu điều kiện phủ định ngắn gọn | Nêu hệ quả ngược lại)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu điều kiện bắt buộc trong văn bản: Provided that, providing, on condition that đều trang trọng hơn if. (Provided that the fee is paid, access continues.)"},{"p":"Nêu điều kiện phủ định ngắn gọn: But for cộng danh từ tương đương if it hadn't been for. (But for the rain, the match would have finished.)"},{"p":"Nêu hệ quả ngược lại: Otherwise đứng ở mệnh đề thứ hai, thường sau dấu chấm phẩy hoặc dấu phẩy. (Book early; otherwise you may not get a seat.)"},{"p":"Nêu giả thiết trong thảo luận: Suppose và supposing mở đầu một tình huống giả định. (Supposing you lost the file, what would you do?)"},{"p":"Ghi nhớ: Provided that, on condition that, but for, otherwise diễn đạt điều kiện với sắc thái trang trọng hơn."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: provided that + mệnh đề | but for + danh từ"},{"table":[["Liên từ / Cụm từ","Công thức / Quy tắc","Ví dụ"],["provided / providing that","+ mệnh đề ở hiện tại đơn","Providing you arrive by nine, you can join."],["on condition that","+ mệnh đề, rất trang trọng","He was released on condition that he reported weekly."],["but for","+ danh từ hoặc cụm danh từ","But for his advice, I would have resigned."],["otherwise / or else","nêu hệ quả nếu điều kiện không thoả","Hurry up, or else we'll be late."],["unless · whether or not","unless + mệnh đề = if … not (trừ phi) | whether (+ or not) = dù có hay không","The target will be missed unless emissions fall sharply. / The gap persists whether or not the outlier is removed."],["given that","Given that + mệnh đề = xét rằng, với điều kiện là","Given that the data are anonymised, they may be shared."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn cấu trúc theo văn phong: Provided that và on condition that thuộc văn phong trang trọng; or else thuộc văn nói. (on condition that ↔ or else)"},{"p":"02. Dùng danh từ sau but for: But for không đi với mệnh đề; muốn dùng mệnh đề thì viết if it hadn't been for. (But for your help, …)"},{"p":"03. Không dùng will sau các liên từ điều kiện: Quy tắc này áp dụng cho mọi cách diễn đạt điều kiện. (provided that the fee is paid)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["But for cộng danh từ","But for your help, we would have failed.\n(Nếu không có sự giúp đỡ của bạn thì chúng tôi đã thất bại.)","But for đi với cụm danh từ your help, tương đương if it hadn't been for your help."],["Điều kiện bắt buộc","Provided that the fee is paid, access to the archive continues.\n(Với điều kiện phí được thanh toán, quyền truy cập vào kho lưu trữ vẫn được duy trì.)","Provided that trang trọng hơn if và thường gặp trong văn bản quy định."],["Rất trang trọng","He was released on condition that he reported to the police weekly.\n(Anh ta được trả tự do với điều kiện phải trình diện cảnh sát mỗi tuần.)","On condition that thường gặp trong văn bản pháp lí."],["Hệ quả ngược lại","Book your ticket early; otherwise you may not get a seat.\n(Hãy mua vé sớm, nếu không bạn có thể không có chỗ.)","Otherwise nêu điều sẽ xảy ra nếu lời khuyên không được thực hiện."],["Giả thiết","Supposing you lost all your data, what would you do?\n(Giả sử bạn mất toàn bộ dữ liệu thì bạn sẽ làm gì?)","Supposing mở đầu một tình huống giả định, thường đi với cấu trúc điều kiện loại 2."],["Văn nói","Hurry up, or else we will miss the opening.\n(Nhanh lên không thì chúng ta sẽ trễ phần mở đầu.)","Or else mang giọng thân mật, gần nghĩa với otherwise."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Chọn cấu trúc theo văn phong"},{"table":[["Cấu trúc","Sắc thái","Ví dụ"],["if","trung tính, dùng được mọi nơi","If you pay, you can enter."],["provided that / as long as","nhấn mạnh điều kiện bắt buộc","Provided that you pay, you can enter."],["on condition that","văn bản pháp lí, hành chính","…on condition that payment is made."],["but for + danh từ","nếu không có","But for the delay, we would have arrived."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: But for you helped us, we would have failed. → Đã sửa: But for your help, we would have failed. — But for chỉ đi với danh từ hoặc cụm danh từ, không đi với mệnh đề."},{"p":"Chưa đúng: Provided that the fee will be paid, access continues. → Đã sửa: Provided that the fee is paid, access continues. — Mệnh đề điều kiện không dùng will."},{"p":"Chưa đúng: Book early, otherwise, you will get a seat. → Đã sửa: Book early; otherwise you may not get a seat. — Otherwise nêu hệ quả tiêu cực khi điều kiện không được thoả."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Cấu trúc đã phù hợp với văn phong của văn bản."},{"p":"But for đi với danh từ, không đi với mệnh đề."},{"p":"Mệnh đề điều kiện không có will."},{"p":"Otherwise nêu hệ quả khi điều kiện không được thoả."}]}],"id":"c1-06"},{"n":7,"title":"Verb complementation patterns","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ở trình độ C1, lỗi dạng thức động từ không còn là chọn V-ing hay to-V mà là chọn đúng mẫu bổ ngữ. Mỗi động từ chỉ chấp nhận một số mẫu nhất định: có động từ đi với mệnh đề that, có động từ cần tân ngữ rồi as hoặc to be, có động từ đi được với mệnh đề wh-. Nhầm mẫu làm câu sai ngữ pháp dù từ vựng hoàn toàn đúng."},{"p":"Cấu trúc chính: V + that + mệnh đề | V + O + as + danh từ | V + O + wh- + mệnh đề"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The study regards the findings as preliminary and argues that further work is needed. (Nêu nhận định bằng mệnh đề that | Xếp loại hoặc đánh giá một đối tượng | Nêu điều chưa xác định bằng mệnh đề wh-)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu nhận định bằng mệnh đề that: Argue, claim, show, suggest, demonstrate, conclude đi với mệnh đề that. (The data show that the trend continues.)"},{"p":"Xếp loại hoặc đánh giá một đối tượng: Regard, view, describe, see, treat cần tân ngữ rồi as; consider dùng được cả as và không as. (They regard it as a success. / They consider it successful.)"},{"p":"Nêu điều chưa xác định bằng mệnh đề wh-: Explain, determine, examine, discuss đi được với mệnh đề wh-. (The paper examines why the policy failed.)"},{"p":"Nêu người nhận thông tin: Tell, inform, remind, convince cần tân ngữ chỉ người trước mệnh đề that. (The author reminds us that the sample was small.)"},{"p":"Ghi nhớ: Mỗi động từ chi phối một mẫu bổ ngữ riêng: mệnh đề that, tân ngữ cộng as hoặc tân ngữ cộng mệnh đề wh-."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: V + that + mệnh đề | V + O + as + danh từ | V + O + wh- + mệnh đề"},{"table":[["Mẫu bổ ngữ","Động từ tiêu biểu","Ví dụ"],["V + that","argue, claim, show, suggest, conclude, demonstrate","He concluded that the model was flawed."],["V + O + as","regard, view, describe, see, treat, define","She described the result as surprising."],["V + O + to be","consider, believe, find, prove (văn phong trang trọng)","The court found the claim to be valid."],["V + O + that","tell, inform, remind, convince, assure","He assured us that the data were accurate."],["Động từ + giới từ cố định","accuse somebody of, insist on, attack/criticise somebody for, credit somebody with (+ V-ing)","accused the editors of ignoring /insisted on seeing / attacked the agency for delaying / credited with spotting"],["Động từ + mệnh đề wh-","determine/ask/explain + where/why/how + mệnh đề","The report determines where the error occurred."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định hành vi ngôn ngữ của động từ: Nêu nhận định, xếp loại, giải thích, hay thông báo cho ai. (argue (nhận định) ↔ regard (xếp loại))"},{"p":"02. Kiểm tra yêu cầu về tân ngữ: Nhóm tell và inform bắt buộc có tân ngữ chỉ người; nhóm say và argue thì không. (inform us that… ↔ argue that…)"},{"p":"03. Kiểm tra động từ có cần as hay không: Regard và view bắt buộc có as; consider thì không bắt buộc. (regard it as useful ↔ consider it useful)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Hai mẫu trong một câu","The study regards the findings as preliminary and argues that further work is needed.\n(Nghiên cứu này coi các phát hiện là sơ bộ và cho rằng cần nghiên cứu thêm.)","Regard cần tân ngữ rồi as; argue đi trực tiếp với mệnh đề that."],["Nêu nhận định","The data show that the upward trend has continued since 2018.\n(Dữ liệu cho thấy xu hướng tăng vẫn tiếp tục từ năm 2018.)","Show đi với mệnh đề that và không cần tân ngữ chỉ người."],["Nêu người nhận thông tin","The author reminds us that the sample was drawn from a single city.\n(Tác giả nhắc chúng ta rằng mẫu chỉ lấy từ một thành phố.)","Remind bắt buộc có tân ngữ chỉ người trước mệnh đề that."],["Mẫu với to be","The committee found the explanation to be inadequate.\n(Hội đồng nhận thấy lời giải thích là chưa thoả đáng.)","Find cộng tân ngữ cộng to be mang giọng trang trọng, thường gặp trong văn bản chính thức."],["Mệnh đề wh-","The paper examines why the policy failed in rural districts.\n(Bài viết xem xét vì sao chính sách thất bại ở các huyện nông thôn.)","Examine đi được với mệnh đề wh- và trật tự là the policy failed."],["Không cần as","Most economists consider the measure necessary.\n(Phần lớn các nhà kinh tế cho rằng biện pháp này là cần thiết.)","Consider không bắt buộc có as; viết consider the measure as necessary thì không tự nhiên."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Bốn mẫu bổ ngữ dễ lẫn"},{"table":[["Mẫu bổ ngữ","Quy tắc","Ví dụ"],["argue that","không cần tân ngữ","She argues that it works."],["remind somebody that","bắt buộc có tân ngữ chỉ người","She reminds us that it works."],["regard something as","bắt buộc có as","She regards it as effective."],["consider something + tính từ","không cần as","She considers it effective."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The study regards that the findings are preliminary. → Đã sửa: The study regards the findings as preliminary. — Regard cần tân ngữ rồi as, không đi với mệnh đề that."},{"p":"Chưa đúng: The author reminds that the sample was small. → Đã sửa: The author reminds us that the sample was small. — Remind bắt buộc có tân ngữ chỉ người."},{"p":"Chưa đúng: The paper examines why did the policy fail. → Đã sửa: The paper examines why the policy failed. — Mệnh đề wh- làm bổ ngữ nên giữ trật tự câu kể và không có trợ động từ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Động từ có cần tân ngữ chỉ người hay không."},{"p":"Động từ có bắt buộc đi với as hay không."},{"p":"Mệnh đề wh- giữ trật tự câu kể."},{"p":"Mẫu bổ ngữ khớp với động từ đã chọn."}]}],"id":"c1-07"},{"n":8,"title":"Reduced relative clauses","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Rút gọn mệnh đề quan hệ giúp câu ngắn gọn và trang trọng hơn, rất thường gặp trong văn viết học thuật và báo chí. Điều kiện để rút gọn là đại từ quan hệ phải làm chủ ngữ của mệnh đề. Sau khi lược, động từ giữ lại ở dạng V-ing nếu nghĩa chủ động, ở dạng quá khứ phân từ nếu nghĩa bị động."},{"p":"Cấu trúc chính: who works → working | which was built → built"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The man standing by the door is our new manager. (Nén thông tin trong văn viết | Diễn đạt nghĩa bị động ngắn gọn | Rút gọn mệnh đề có tính từ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nén thông tin trong văn viết: Lược bỏ đại từ quan hệ và trợ động từ để câu gọn hơn. (the people waiting outside)"},{"p":"Diễn đạt nghĩa bị động ngắn gọn: Dùng quá khứ phân từ khi danh từ là đối tượng chịu tác động. (the bridge built in 1998)"},{"p":"Rút gọn mệnh đề có tính từ: Lược bỏ who is, which are rồi giữ lại phần còn lại. (the students present at the meeting)"},{"p":"Rút gọn bằng to-V: Dùng khi mệnh đề quan hệ mang nghĩa dự định hoặc thứ tự xếp hạng. (the first person to arrive)"},{"p":"Ghi nhớ: Lược đại từ quan hệ và động từ be, giữ lại V-ing cho nghĩa chủ động và V3 cho nghĩa bị động."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: who works → working | which was built → built"},{"table":[["Dạng rút gọn","Công thức / Quy tắc","Ví dụ"],["Chủ động","who/which + V → V-ing","the man who stands → the man standing"],["Bị động","which was/were + V3 → V3","the house which was built → the house built"],["Có tính từ hoặc trạng ngữ","who/which + be + tính từ → tính từ","the people who are responsible → the people responsible"],["Dùng to-V","the first/last/only + danh từ + to-V","the only student to pass"],["V3 bất quy tắc trong rút gọn","made, sent, taken, given đứng ngay sau danh từ mang nghĩa bị động","cars made in Japan / letters sent last week"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xét vai trò của đại từ quan hệ: Chỉ rút gọn được khi đại từ quan hệ làm chủ ngữ của mệnh đề. (the man who lives here → the man living here)"},{"p":"02. Lược đại từ quan hệ và be: Phần be bị lược, động từ chính giữ lại ở dạng phân từ. (which is waiting → waiting)"},{"p":"03. Chọn V-ing hoặc V3 theo nghĩa: Danh từ thực hiện hành động thì dùng V-ing; chịu tác động thì dùng V3. (the woman carrying the box ↔ the box carried by the woman)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Chủ động","The man standing by the door is our new manager.\n(Người đàn ông đứng ở cửa là quản lí mới của chúng tôi.)","Đầy đủ là the man who is standing; lược who is rồi giữ standing."],["Bị động","The bridge built in 1998 is now being repaired.\n(Cây cầu xây năm 1998 giờ đang được sửa.)","Đầy đủ là the bridge which was built; cây cầu là đối tượng chịu tác động nên dùng quá khứ phân từ."],["Nghĩa thường lệ","Students living on campus receive a discount.\n(Sinh viên ở trong khu nội trú được giảm giá.)","Mệnh đề gốc là who live, dạng hiện tại đơn, nhưng khi rút gọn vẫn thành V-ing."],["Rút gọn với tính từ","All the documents relevant to the case were copied.\n(Toàn bộ tài liệu liên quan đến vụ việc đã được sao lại.)","Đầy đủ là which were relevant; lược which were rồi giữ tính từ."],["Dùng to-V","She was the first woman to lead the department.\n(Cô ấy là người phụ nữ đầu tiên lãnh đạo phòng này.)","Sau the first, the last, the only thì rút gọn bằng to-V."],["Hai mệnh đề rút gọn","The report written last month and the data collected this week are both available.\n(Báo cáo viết tháng trước và dữ liệu thu thập tuần này đều đã có.)","Hai cụm rút gọn song song, cả hai đều mang nghĩa bị động nên dùng quá khứ phân từ."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Chọn dạng phân từ theo nghĩa"},{"table":[["Dạng thức","Quy tắc","Ví dụ"],["V-ing","danh từ thực hiện hành động","the girl playing the piano"],["V3","danh từ chịu tác động","the piano played by the girl"],["to-V","sau the first, the last, the only hoặc nghĩa dự định","the next train to leave"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The man stands by the door is our new manager. → Đã sửa: The man standing by the door is our new manager. — Sau khi lược đại từ quan hệ, động từ phải ở dạng phân từ, không ở dạng đã chia."},{"p":"Chưa đúng: The bridge building in 1998 is now being repaired. → Đã sửa: The bridge built in 1998 is now being repaired. — Cây cầu chịu tác động nên dùng quá khứ phân từ."},{"p":"Chưa đúng: The book which I read it is on the table, reduced to the book read I. → Đã sửa: The book I read is on the table. — Khi đại từ quan hệ làm tân ngữ thì chỉ lược được đại từ, không rút gọn thành phân từ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Đại từ quan hệ làm chủ ngữ của mệnh đề."},{"p":"Đại từ quan hệ và động từ be đã được lược."},{"p":"Dạng phân từ phù hợp với nghĩa chủ động hoặc bị động."},{"p":"Cụm rút gọn đứng ngay sau danh từ được bổ nghĩa."}]}],"id":"c1-08"},{"n":9,"title":"Participle clauses","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Mệnh đề phân từ nén một mệnh đề trạng ngữ thành một cụm không có chủ ngữ riêng, nhờ đó câu gọn và mạch văn liền hơn. Điều kiện bắt buộc là chủ ngữ của cụm phân từ phải trùng với chủ ngữ của mệnh đề chính. Vi phạm điều kiện này tạo ra lỗi phân từ treo, một lỗi nặng trong văn viết học thuật."},{"p":"Cấu trúc chính: Having + V3, S + V | V-ing, S + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Having finished the report, she went home. (Diễn tả hai việc cùng lúc | Diễn tả việc xảy ra trước | Nêu nguyên nhân)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Diễn tả hai việc cùng lúc: V-ing mở đầu cho hành động diễn ra đồng thời với mệnh đề chính. (Walking home, I met an old friend.)"},{"p":"Diễn tả việc xảy ra trước: Having cộng quá khứ phân từ cho biết việc đã hoàn tất trước mệnh đề chính. (Having read the report, he signed it.)"},{"p":"Nêu nguyên nhân: Cụm phân từ thay cho mệnh đề với because hoặc as. (Being tired, she went to bed early.)"},{"p":"Diễn tả nghĩa bị động: Quá khứ phân từ mở đầu khi chủ ngữ chịu tác động. (Written in 1920, the novel still feels modern.)"},{"p":"Ghi nhớ: Rút gọn mệnh đề trạng ngữ bằng V-ing, V3 hoặc having + V3, với điều kiện cùng chủ ngữ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: Having + V3, S + V | V-ing, S + V"},{"table":[["Quan hệ / Dạng","Công thức","Ví dụ"],["Đồng thời","V-ing, S + V","Opening the door, she saw the mess."],["Xảy ra trước","Having + V3, S + V","Having eaten, we left."],["Bị động","V3, S + V / Having been + V3, S + V","Built in 1990, the hall needs repairs."],["Có liên từ","after/before/while/when + V-ing","After checking the figures, he called the client."],["Given + cụm danh từ","Given + cụm danh từ = xét tới, tính tới","Given the sample size, the confidence interval is wide."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Kiểm tra hai mệnh đề có cùng chủ ngữ: Nếu khác chủ ngữ thì không rút gọn được, nếu rút gọn sẽ thành lỗi phân từ treo. (Having finished the report, she went home.)"},{"p":"02. Chọn dạng phân từ theo quan hệ thời gian: Đồng thời dùng V-ing, xảy ra trước dùng having cộng V3, bị động dùng V3. (Walking home ↔ Having walked home)"},{"p":"03. Đặt dấu phẩy sau cụm phân từ: Cụm phân từ mở đầu câu luôn được tách bằng dấu phẩy. (Being new here, I need help.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Xảy ra trước","Having finished the report, she went home.\n(Làm xong báo cáo, cô ấy về nhà.)","Hai mệnh đề cùng chủ ngữ she; having finished cho biết việc hoàn tất trước."],["Đồng thời","Walking home from school, I met an old friend.\n(Trên đường từ trường về, tôi gặp một người bạn cũ.)","Hai việc diễn ra cùng lúc nên dùng V-ing."],["Nêu nguyên nhân","Being tired after the trip, she went to bed early.\n(Vì mệt sau chuyến đi, cô ấy đi ngủ sớm.)","Cụm phân từ thay cho mệnh đề with because; chủ ngữ vẫn là she."],["Bị động","Written in 1920, the novel still feels surprisingly modern.\n(Viết năm 1920, quyển tiểu thuyết vẫn mang cảm giác hiện đại.)","Chủ ngữ the novel chịu tác động nên dùng quá khứ phân từ mở đầu."],["Có liên từ","After checking the figures again, he called the client.\n(Sau khi kiểm tra lại số liệu, anh ấy gọi cho khách hàng.)","Liên từ after đứng trước V-ing giúp quan hệ thời gian rõ hơn."],["Bị động xảy ra trước","Having been notified of the delay, the passengers changed platforms.\n(Sau khi được thông báo về sự chậm trễ, hành khách đổi sân ga.)","Having been cộng quá khứ phân từ diễn tả nghĩa bị động và xảy ra trước."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba dạng mệnh đề phân từ"},{"table":[["Dạng thức","Ý nghĩa","Ví dụ"],["V-ing","đồng thời hoặc nguyên nhân, nghĩa chủ động","Feeling unwell, he left."],["Having + V3","xảy ra trước, nghĩa chủ động","Having eaten, he left."],["V3 / Having been + V3","nghĩa bị động","Rejected twice, he tried again."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Having finished the report, the office was closed. → Đã sửa: Having finished the report, she found the office closed. — Chủ ngữ của cụm phân từ phải trùng với chủ ngữ mệnh đề chính; đây là lỗi phân từ treo."},{"p":"Chưa đúng: Walking home, my phone rang. → Đã sửa: Walking home, I heard my phone ring. — Chiếc điện thoại không thể là chủ thể của việc đi bộ về nhà."},{"p":"Chưa đúng: Written in 1920, the author still feels modern. → Đã sửa: Written in 1920, the novel still feels modern. — Quá khứ phân từ phải mô tả đối tượng chịu tác động, ở đây là quyển tiểu thuyết."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Hai mệnh đề có cùng chủ ngữ."},{"p":"Dạng phân từ phù hợp với quan hệ thời gian và nghĩa."},{"p":"Cụm phân từ mở đầu được tách bằng dấu phẩy."},{"p":"Không tạo ra lỗi phân từ treo."}]}],"id":"c1-09"},{"n":10,"title":"Negative inversion","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Đưa một trạng từ phủ định lên đầu câu tạo sắc thái nhấn mạnh, thường gặp trong văn viết trang trọng và văn chương. Khi đó, trợ động từ đứng trước chủ ngữ như trong câu hỏi. Nếu câu chưa có trợ động từ, cần thêm do, does hoặc did."},{"p":"Cấu trúc chính: Never/Seldom/Rarely + trợ động từ + S + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Never have I seen such a crowd. (Nhấn mạnh sự hiếm có | Nhấn mạnh trong văn chương và diễn văn | Nhấn mạnh phạm vi phủ định)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nhấn mạnh sự hiếm có: Never, rarely, seldom, little mở đầu câu để gây ấn tượng. (Rarely does one encounter such precision.)"},{"p":"Nhấn mạnh trong văn chương và diễn văn: Cấu trúc này tạo giọng trang trọng, không dùng trong hội thoại thông thường. (Never before had the country faced such a crisis.)"},{"p":"Nhấn mạnh phạm vi phủ định: Các cụm như at no time, under no circumstances, on no account cũng kéo theo đảo ngữ. (Under no circumstances should you open this door.)"},{"p":"Nhấn mạnh với little và nowhere: Little mang nghĩa phủ định khi mở đầu câu đảo ngữ. (Little did she know what was coming.)"},{"p":"Ghi nhớ: Khi trạng từ phủ định đứng đầu câu, trợ động từ đảo lên trước chủ ngữ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: Never/Seldom/Rarely + trợ động từ + S + V"},{"table":[["Trường hợp","Công thức / Quy tắc","Ví dụ"],["Có trợ động từ","trạng từ phủ định + trợ động từ + S + động từ chính","Never have I seen…"],["Không có trợ động từ","thêm do/does/did","Rarely does he complain."],["Với động từ to be","đảo chính to be","Seldom is the answer so simple."],["Cụm phủ định","at no time, under no circumstances, on no account, in no way","At no time was the public informed."],["Trợ động từ sau trạng ngữ phủ định","Nowhere/On no account + will/can/must + S + V (khuyết thiếu cũng đảo như trợ động từ)","Nowhere will you find a better example. / On no account can raw data be shared."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đưa trạng từ phủ định lên đầu câu: Chỉ các trạng từ mang nghĩa phủ định hoặc hạn định mới kéo theo đảo ngữ. (Never, Rarely, Seldom, Little, Nowhere)"},{"p":"02. Đảo trợ động từ lên trước chủ ngữ: Trật tự giống câu hỏi, nhưng câu vẫn là câu kể và kết thúc bằng dấu chấm. (Never have I seen…)"},{"p":"03. Thêm do, does hoặc did khi cần: Khi đã có trợ động từ thì động từ chính trở về dạng nguyên mẫu. (Rarely does he complain.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Với hiện tại hoàn thành","Never have I seen such a crowd at the festival.\n(Chưa bao giờ tôi thấy đông người như vậy ở lễ hội.)","Trợ động từ have đảo lên trước chủ ngữ I; câu vẫn là câu kể."],["Thêm does","Rarely does he complain about the workload.\n(Anh ấy rất ít khi phàn nàn về khối lượng công việc.)","Câu gốc không có trợ động từ nên phải thêm does và complain trở về nguyên mẫu."],["Với to be","Seldom is the answer so straightforward.\n(Câu trả lời ít khi rõ ràng như vậy.)","Động từ to be tự đảo, không cần thêm trợ động từ."],["Cụm phủ định","Under no circumstances should you share this password.\n(Trong mọi trường hợp, bạn không được chia sẻ mật khẩu này.)","Cụm under no circumstances kéo theo đảo ngữ với động từ khuyết thiếu should."],["Little mang nghĩa phủ định","Little did she know that the decision would change everything.\n(Cô ấy nào biết quyết định đó sẽ thay đổi mọi thứ.)","Little ở đầu câu mang nghĩa phủ định và kéo theo đảo ngữ với did."],["At no time","At no time was the public informed about the risk.\n(Công chúng chưa từng được thông báo về nguy cơ này.)","Cụm at no time kéo theo đảo ngữ, ở đây với động từ be trong câu bị động."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Trật tự thường và trật tự đảo ngữ"},{"table":[["Kiểu trật tự","Quy tắc","Ví dụ"],["trật tự thường","trạng từ ở giữa câu, không đảo","I have never seen such a crowd."],["đảo ngữ","trạng từ ở đầu, trợ động từ đảo lên","Never have I seen such a crowd."],["thêm do/does/did","khi câu gốc không có trợ động từ","He rarely complains. → Rarely does he complain."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Never I have seen such a crowd. → Đã sửa: Never have I seen such a crowd. — Trạng từ phủ định ở đầu câu bắt buộc kéo theo đảo ngữ."},{"p":"Chưa đúng: Rarely he complains about the workload. → Đã sửa: Rarely does he complain about the workload. — Câu không có trợ động từ thì phải thêm does và động từ chính về nguyên mẫu."},{"p":"Chưa đúng: Never have I seen such a crowd? → Đã sửa: Never have I seen such a crowd. — Đảo ngữ nhấn mạnh không phải câu hỏi nên kết thúc bằng dấu chấm."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Trạng từ mở đầu có mang nghĩa phủ định hoặc hạn định."},{"p":"Trợ động từ đã đảo lên trước chủ ngữ."},{"p":"Do, does hoặc did được thêm khi cần, và động từ chính về nguyên mẫu."},{"p":"Câu kết thúc bằng dấu chấm, không phải dấu hỏi."}]}],"id":"c1-10"},{"n":11,"title":"Hardly, no sooner & not only","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Nhóm cấu trúc này diễn tả hai sự việc xảy ra sát nhau hoặc bổ sung thêm một ý cùng hướng. Hardly và scarcely đi với when; no sooner đi với than. Vế đầu luôn đảo trợ động từ lên trước chủ ngữ."},{"p":"Cấu trúc chính: Hardly had S + V3 when … | No sooner had S + V3 than …"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): No sooner had we sat down than the lights went out. (Nhấn mạnh hai việc xảy ra sát nhau | Nhấn mạnh sự nhanh chóng | Thêm một thông tin đáng chú ý)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nhấn mạnh hai việc xảy ra sát nhau: Vế đầu ở quá khứ hoàn thành, vế sau ở quá khứ đơn. (Hardly had he arrived when the meeting began.)"},{"p":"Nhấn mạnh sự nhanh chóng: No sooner nhấn mạnh rằng việc thứ hai xảy ra ngay lập tức. (No sooner had she spoken than everyone fell silent.)"},{"p":"Thêm một thông tin đáng chú ý: Not only … but also nối hai thông tin, vế đầu đảo ngữ khi not only mở đầu câu. (Not only did he apologise, but he also offered to pay.)"},{"p":"Nhấn mạnh trong văn viết trang trọng: Các cấu trúc này thuộc văn phong trang trọng và văn kể. (Scarcely had the ink dried when the order was revoked.)"},{"p":"Ghi nhớ: Hardly … when, no sooner … than, not only … but also đều kéo theo đảo ngữ ở vế đầu."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: Hardly had S + V3 when … | No sooner had S + V3 than …"},{"table":[["Cấu trúc","Công thức / Quy tắc","Ví dụ"],["hardly / scarcely … when","Hardly had + S + V3 + when + quá khứ đơn","Hardly had I left when it rained."],["no sooner … than","No sooner had + S + V3 + than + quá khứ đơn","No sooner had I left than it rained."],["not only … but also","Not only + trợ động từ + S + V, but + S + also + V","Not only was she late, but she also forgot the file."],["trật tự thường","các cấu trúc này cũng viết được không đảo khi không mở đầu câu","He had hardly arrived when the meeting began."],["Not only + trợ động từ","Not only + is/does/did + S … (be tự đảo; động từ thường mượn do/does/did)","Not only is this method faster… / Not only does the method cost less…"],["So + tính từ","So + tính từ + be + S + that + mệnh đề kết quả","So large was the discrepancy that the run was repeated."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đưa cấu trúc nhấn mạnh lên đầu câu: Vế đầu thường ở quá khứ hoàn thành với trợ động từ had. (No sooner had we sat down…)"},{"p":"02. Chọn đúng từ nối cho vế sau: Hardly và scarcely đi với when; no sooner đi với than. (…than the lights went out.)"},{"p":"03. Chia vế sau ở quá khứ đơn: Vế sau nêu việc xảy ra ngay sau đó nên dùng quá khứ đơn. (when the meeting began)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["No sooner … than","No sooner had we sat down than the lights went out.\n(Chúng tôi vừa ngồi xuống thì đèn tắt.)","No sooner bắt buộc đi với than, không đi với when."],["Hardly … when","Hardly had he arrived when the meeting began.\n(Anh ấy vừa đến thì cuộc họp bắt đầu.)","Hardly đi với when; vế đầu ở quá khứ hoàn thành, vế sau ở quá khứ đơn."],["Scarcely … when","Scarcely had the ink dried when the order was revoked.\n(Mực vừa khô thì lệnh bị thu hồi.)","Scarcely dùng như hardly và cũng đi với when."],["Not only mở đầu câu","Not only did he apologise, but he also offered to pay for the damage.\n(Anh ấy không chỉ xin lỗi mà còn đề nghị trả tiền sửa chữa.)","Not only ở đầu câu kéo theo đảo ngữ với did; also đứng sau chủ ngữ ở vế hai."],["Not only với to be","Not only was she late, but she also forgot the documents.\n(Cô ấy không chỉ đến muộn mà còn quên tài liệu.)","Động từ to be tự đảo, không cần thêm did."],["Trật tự thường","He had hardly arrived when the meeting began.\n(Anh ấy vừa đến thì cuộc họp bắt đầu.)","Khi hardly không mở đầu câu thì không cần đảo ngữ, giọng cũng bình thường hơn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ghép đúng cặp từ nối"},{"table":[["Từ mở đầu","Từ nối vế sau","Ví dụ"],["hardly / scarcely","đi với when","Hardly had I spoken when he left."],["no sooner","đi với than","No sooner had I spoken than he left."],["not only","đi với but also","Not only did I speak, but I also wrote."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: No sooner had we sat down when the lights went out. → Đã sửa: No sooner had we sat down than the lights went out. — No sooner bắt buộc đi với than."},{"p":"Chưa đúng: Hardly he had arrived when the meeting began. → Đã sửa: Hardly had he arrived when the meeting began. — Hardly ở đầu câu kéo theo đảo trợ động từ had lên trước chủ ngữ."},{"p":"Chưa đúng: Not only he apologised, but he also paid. → Đã sửa: Not only did he apologise, but he also paid. — Not only ở đầu câu đòi hỏi đảo ngữ và câu không có trợ động từ nên thêm did."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Cặp từ nối đã ghép đúng: when với hardly, than với no sooner."},{"p":"Vế đầu đảo trợ động từ lên trước chủ ngữ."},{"p":"Vế đầu ở quá khứ hoàn thành, vế sau ở quá khứ đơn."},{"p":"Not only kéo theo đảo ngữ và also đứng sau chủ ngữ ở vế hai."}]}],"id":"c1-11"},{"n":12,"title":"Conditional inversion","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Trong văn bản trang trọng, câu điều kiện thường bỏ if và đảo trợ động từ lên trước chủ ngữ. Chỉ ba từ cho phép cấu trúc này: should cho điều kiện loại 1, were cho loại 2, và had cho loại 3. Cấu trúc này rất thường gặp trong thư thương mại, hợp đồng và văn bản học thuật."},{"p":"Cấu trúc chính: Should/Were/Had + S + …"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Should you need any help, please contact us. (Thư từ và văn bản trang trọng | Nêu khả năng ít xảy ra | Điều kiện giả định trái hiện tại)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Thư từ và văn bản trang trọng: Should you cộng động từ nguyên mẫu là mẫu mở đầu lịch sự rất phổ biến. (Should you require further information, please write.)"},{"p":"Nêu khả năng ít xảy ra: Should làm cho điều kiện nghe xa hơn và lịch sự hơn if. (Should the system fail, restart it.)"},{"p":"Điều kiện giả định trái hiện tại: Were to cộng động từ nguyên mẫu nhấn mạnh tính giả định. (Were she to resign, the team would struggle.)"},{"p":"Điều kiện trái quá khứ: Had cộng chủ ngữ cộng quá khứ phân từ thay cho if cộng quá khứ hoàn thành. (Had we known, we would have acted.)"},{"p":"Ghi nhớ: Bỏ if và đảo should, were hoặc had lên trước chủ ngữ để tạo giọng trang trọng."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: Should/Were/Had + S + …"},{"table":[["Loại điều kiện","Công thức","Ví dụ"],["Loại 1 trang trọng","Should + S + V nguyên mẫu, …","Should you change your mind, let me know."],["Loại 2","Were + S + …, / Were + S + to-V, …","Were I in your position, I would accept."],["Loại 3","Had + S + V3, …","Had they arrived earlier, they would have seen her."],["Phủ định","không rút gọn: Were it not for … / Had it not been for …","Had it not been for your help, we would have failed."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Bỏ if ở đầu mệnh đề điều kiện: Chỉ bỏ if, các thành phần khác giữ nguyên nghĩa. (If you need help → Should you need help)"},{"p":"02. Đảo should, were hoặc had lên trước chủ ngữ: Loại 1 dùng should, loại 2 dùng were, loại 3 dùng had. (Had we known…)"},{"p":"03. Không rút gọn dạng phủ định: Viết were it not hoặc had it not been, không viết weren't hoặc hadn't trong cấu trúc đảo. (Were it not for the rain, …)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Thư trang trọng","Should you need any help, please contact our office.\n(Nếu quý vị cần hỗ trợ, xin liên hệ văn phòng của chúng tôi.)","Mẫu should you là cách mở đầu lịch sự rất phổ biến trong thư thương mại."],["Loại 2 với were","Were I in your position, I would accept the offer.\n(Nếu tôi ở vị trí của bạn thì tôi sẽ nhận lời.)","Were đảo lên trước chủ ngữ I, tương đương if I were."],["Were to nhấn mạnh giả định","Were she to resign, the whole team would struggle.\n(Nếu cô ấy từ chức thì cả nhóm sẽ gặp khó.)","Were to cộng động từ nguyên mẫu nhấn mạnh rằng khả năng này chỉ là giả định."],["Loại 3 với had","Had we known about the delay, we would have rebooked.\n(Nếu biết về việc hoãn, chúng tôi đã đổi vé.)","Had đảo lên trước chủ ngữ we, tương đương if we had known."],["Phủ định không rút gọn","Had it not been for your help, we would have failed.\n(Nếu không có sự giúp đỡ của bạn thì chúng tôi đã thất bại.)","Trong cấu trúc đảo, dạng phủ định không rút gọn thành hadn't."],["Loại 1 với động từ khuyết thiếu","Should the system fail, restart it and inform the team.\n(Nếu hệ thống gặp lỗi, hãy khởi động lại và thông báo cho nhóm.)","Mệnh đề chính có thể ở dạng mệnh lệnh, rất thường gặp trong tài liệu hướng dẫn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba từ mở đầu đảo ngữ điều kiện"},{"table":[["Cấu trúc mở đầu","Loại điều kiện","Ví dụ"],["Should + S + V","loại 1, trang trọng","Should you wish to cancel, …"],["Were + S","loại 2, giả định hiện tại","Were he here, …"],["Had + S + V3","loại 3, trái quá khứ","Had she called, …"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Should you will need any help, please contact us. → Đã sửa: Should you need any help, please contact us. — Sau should là động từ nguyên mẫu, không dùng will."},{"p":"Chưa đúng: Was I in your position, I would accept. → Đã sửa: Were I in your position, I would accept. — Cấu trúc đảo của điều kiện loại 2 chỉ dùng were."},{"p":"Chưa đúng: Hadn't we known about the delay, we would have rebooked. → Đã sửa: Had we not known about the delay, we would have rebooked. — Trong cấu trúc đảo, dạng phủ định không được rút gọn."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"If đã được bỏ và trợ động từ đã đảo lên trước chủ ngữ."},{"p":"Should, were hoặc had chọn đúng theo loại điều kiện."},{"p":"Sau should là động từ nguyên mẫu, không có will."},{"p":"Dạng phủ định không bị rút gọn."}]}],"id":"c1-12"},{"n":13,"title":"Cleft sentences","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Câu chẻ tách một câu thường thành hai phần để làm nổi bật một thành phần cụ thể, thường nhằm sửa lại một thông tin sai hoặc nhấn mạnh điều quan trọng nhất. Có hai dạng chính: dạng với it dùng để nhấn mạnh một thành phần riêng lẻ, và dạng với what dùng để nhấn mạnh toàn bộ một ý."},{"p":"Cấu trúc chính: It is/was X that … | What + mệnh đề + is …"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): It was Mai who found the mistake. (Nhấn mạnh chủ ngữ hoặc tân ngữ | Sửa lại thông tin sai | Nhấn mạnh toàn bộ một ý)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nhấn mạnh chủ ngữ hoặc tân ngữ: Dạng it is X that đưa thành phần cần nhấn vào ngay sau to be. (It was the manager who signed it.)"},{"p":"Sửa lại thông tin sai: Câu chẻ rất hay dùng để điều chỉnh điều người nghe hiểu nhầm. (It wasn't me who called - it was Nam.)"},{"p":"Nhấn mạnh toàn bộ một ý: Dạng what cộng mệnh đề đưa cả ý lên làm chủ ngữ. (What we need is more time.)"},{"p":"Nhấn mạnh thời gian, nơi chốn hoặc lí do: Thay that bằng when, where hoặc dùng the reason why. (It was in Hue that we first met.)"},{"p":"Ghi nhớ: Tách câu thành hai phần để đưa một thành phần vào vị trí nổi bật."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: It is/was X that … | What + mệnh đề + is …"},{"table":[["Dạng câu chẻ","Công thức","Ví dụ"],["Dạng với it","It is/was + thành phần nhấn + that/who + phần còn lại","It was Mai who found the mistake."],["Dạng với what","What + mệnh đề + is/was + phần nhấn","What surprised me was his reaction."],["Nhấn mạnh hành động","What + S + do/did + is/was + V nguyên mẫu","What she did was call the police."],["Nhấn mạnh lí do","The reason why … is/was that …","The reason why he left was that he felt unwell."],["All (that) … does is","All (that) + S + does is + V nguyên mẫu không to","All the correction does is change one decimal place."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn thành phần cần nhấn mạnh: Thành phần đó sẽ được đặt ngay sau to be trong dạng với it. (It was Mai…)"},{"p":"02. Giữ từ nối that hoặc who: Thiếu từ nối là lỗi phổ biến nhất của câu chẻ. (…who found the mistake.)"},{"p":"03. Hòa hợp động từ với thành phần nhấn: Mệnh đề what được xem là số ít, nhưng động từ sau nó hòa hợp với phần nhấn. (What we need is time. / What we need are facts.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Nhấn mạnh chủ ngữ","It was Mai who found the mistake in the figures.\n(Chính Mai là người phát hiện ra lỗi trong số liệu.)","Who nối sang phần còn lại; thiếu who thì câu sai ngữ pháp."],["Sửa thông tin","It wasn't me who called you - it was Nam.\n(Không phải tôi gọi cho bạn, mà là Nam.)","Câu chẻ rất hay dùng để điều chỉnh một thông tin bị hiểu sai."],["Nhấn mạnh nơi chốn","It was in Hue that we first met.\n(Chính ở Huế chúng tôi gặp nhau lần đầu.)","Khi nhấn mạnh trạng ngữ nơi chốn thì dùng that, không dùng where."],["Dạng với what","What we need most at the moment is more time.\n(Điều chúng ta cần nhất lúc này là thêm thời gian.)","Mệnh đề what làm chủ ngữ và động từ is hòa hợp với phần nhấn more time."],["Nhấn mạnh hành động","What she did was call the police immediately.\n(Việc cô ấy làm là gọi cảnh sát ngay.)","Sau is hoặc was trong mẫu này, động từ ở dạng nguyên mẫu không to."],["Nhấn mạnh lí do","The reason why he resigned was that he disagreed with the new policy.\n(Lí do anh ấy từ chức là vì không đồng tình với chính sách mới.)","Sau was dùng that cộng mệnh đề, không dùng because."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai dạng câu chẻ"},{"table":[["Cấu trúc","Chức năng","Ví dụ"],["It is/was X that …","nhấn một thành phần riêng lẻ","It was yesterday that she called."],["What … is/was X","nhấn toàn bộ một ý","What she wanted was an apology."],["All … is/was X","nhấn với sắc thái chỉ có thế","All I want is a quiet evening."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: It was Mai found the mistake. → Đã sửa: It was Mai who found the mistake. — Câu chẻ cần từ nối that hoặc who."},{"p":"Chưa đúng: What we need is more facts. → Đã sửa: What we need are more facts. — Động từ hòa hợp với phần nhấn more facts ở số nhiều."},{"p":"Chưa đúng: The reason why he left was because he felt unwell. → Đã sửa: The reason why he left was that he felt unwell. — Sau the reason why … was thì dùng that, không dùng because."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Thành phần cần nhấn mạnh đã đặt đúng vị trí."},{"p":"Từ nối that hoặc who không bị thiếu."},{"p":"Động từ hòa hợp với phần nhấn trong dạng what."},{"p":"Sau the reason why … was thì dùng that."}]}],"id":"c1-13"},{"n":14,"title":"Subjunctive mood","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Thức giả định dùng động từ ở dạng nguyên mẫu không chia trong mệnh đề that, bất kể chủ ngữ là ngôi nào và bất kể thì của mệnh đề chính. Nó xuất hiện sau các động từ và tính từ nêu sự cần thiết, yêu cầu hoặc đề nghị. Đây là nét đặc trưng của văn phong trang trọng, nhất là trong văn bản hành chính và học thuật."},{"p":"Cấu trúc chính: that + S + V nguyên mẫu"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The committee insisted that he resign immediately. (Sau động từ nêu yêu cầu | Sau tính từ nêu sự cần thiết | Sau danh từ tương ứng)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Sau động từ nêu yêu cầu: Demand, insist, request, require, recommend, suggest, propose. (They requested that the meeting be postponed.)"},{"p":"Sau tính từ nêu sự cần thiết: It is essential, vital, important, necessary, advisable that … (It is essential that every form be signed.)"},{"p":"Sau danh từ tương ứng: Demand, requirement, recommendation, proposal that … (His proposal that the rule be changed was accepted.)"},{"p":"Dạng phủ định và bị động: Phủ định là that cộng chủ ngữ cộng not cộng động từ nguyên mẫu; bị động dùng be cộng quá khứ phân từ. (We insist that he not be told. / It is vital that it be checked.)"},{"p":"Ghi nhớ: Sau các động từ và tính từ chỉ sự cần thiết, mệnh đề that dùng động từ nguyên mẫu không chia."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: that + S + V nguyên mẫu"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Khẳng định","that + S + V nguyên mẫu (không -s, không to)","that she arrive on time"],["Phủ định","that + S + not + V nguyên mẫu","that he not leave early"],["Bị động","that + S + be + V3","that the report be submitted"],["Dạng thay thế","should + V nguyên mẫu (phổ biến trong tiếng Anh-Anh)","that she should arrive on time"],["were giả định","as if / if only / wish + S + were (mọi ngôi đều were, kể cả số ít)","The abstract reads as if the result were conclusive. / If only the archive were complete…"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Nhận diện từ chi phối mệnh đề: Nhóm từ này đều mang nghĩa yêu cầu, đề nghị hoặc nêu sự cần thiết. (insist that, essential that)"},{"p":"02. Dùng động từ nguyên mẫu trong mệnh đề that: Không thêm -s với ngôi thứ ba số ít và không lùi thì theo mệnh đề chính. (insisted that he resign)"},{"p":"03. Đặt not trước động từ trong dạng phủ định: Không dùng doesn't hay didn't trong mệnh đề giả định. (that he not be informed)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Sau động từ insist","The committee insisted that he resign immediately.\n(Hội đồng yêu cầu ông ấy từ chức ngay.)","Dù mệnh đề chính ở quá khứ và chủ ngữ là he, động từ vẫn là resign ở dạng nguyên mẫu."],["Sau tính từ","It is essential that every form be signed before submission.\n(Nhất thiết phải kí vào mọi mẫu đơn trước khi gửi.)","Dạng bị động trong thức giả định là be cộng quá khứ phân từ, không phải is."],["Sau danh từ","His proposal that the rule be changed was accepted.\n(Đề xuất của ông về việc thay đổi quy định đã được chấp thuận.)","Danh từ proposal cũng kéo theo thức giả định trong mệnh đề that."],["Dạng phủ định","We insist that he not be told about the decision yet.\n(Chúng tôi đề nghị chưa thông báo cho anh ấy về quyết định này.)","Phủ định đặt not ngay trước động từ, không dùng doesn't."],["Sau recommend","The doctor recommended that she take a week off.\n(Bác sĩ khuyên cô ấy nghỉ một tuần.)","Take giữ dạng nguyên mẫu dù chủ ngữ là she."],["Dạng với should","The board requested that the report should be revised.\n(Ban lãnh đạo đề nghị chỉnh sửa lại báo cáo.)","Dạng với should phổ biến trong tiếng Anh- Anh và mang nghĩa như thức giả định."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Thức giả định và mệnh đề thường"},{"table":[["Cấu trúc","Sắc thái","Ví dụ"],["insist that + V nguyên mẫu","yêu cầu, thức giả định","I insist that he leave."],["insist that + mệnh đề thường","khẳng định một sự thật","He insists that he left early."],["suggest + V-ing","đề nghị, không dùng mệnh đề that","I suggest leaving now."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The committee insisted that he resigns immediately. → Đã sửa: The committee insisted that he resign immediately. — Thức giả định dùng động từ nguyên mẫu, không thêm -s."},{"p":"Chưa đúng: It is essential that every form is signed. → Đã sửa: It is essential that every form be signed. — Dạng bị động trong thức giả định là be cộng quá khứ phân từ."},{"p":"Chưa đúng: We insist that he doesn't be told. → Đã sửa: We insist that he not be told. — Phủ định của thức giả định đặt not trước động từ, không dùng trợ động từ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Từ chi phối thuộc nhóm nêu yêu cầu hoặc sự cần thiết."},{"p":"Động từ trong mệnh đề that ở dạng nguyên mẫu không chia."},{"p":"Dạng bị động dùng be cộng quá khứ phân từ."},{"p":"Phủ định đặt not trước động từ, không dùng trợ động từ."}]}],"id":"c1-14"},{"n":15,"title":"It's time & would rather","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Hai cấu trúc này dùng quá khứ đơn không để chỉ thời gian mà để đánh dấu tính giả định, giống như trong câu điều kiện loại 2. It's time cộng chủ ngữ cộng quá khứ đơn hàm ý việc đó lẽ ra nên làm rồi. Would rather đổi dạng theo việc chủ ngữ của hai mệnh đề có trùng nhau hay không."},{"p":"Cấu trúc chính: It's time + S + quá khứ đơn | would rather + S + quá khứ đơn"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): It's time we left for the airport. (Nhắc rằng đã đến lúc phải làm | Nhấn mạnh sự chậm trễ | Nêu điều mình muốn hơn cho bản thân)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nhắc rằng đã đến lúc phải làm: It's time cộng chủ ngữ cộng quá khứ đơn mang sắc thái phê bình nhẹ. (It's time you took this seriously.)"},{"p":"Nhấn mạnh sự chậm trễ: It's high time và it's about time làm sắc thái phê bình rõ hơn. (It's high time she apologised.)"},{"p":"Nêu điều mình muốn hơn cho bản thân: Would rather cộng động từ nguyên mẫu khi chỉ có một chủ ngữ. (I'd rather stay at home tonight.)"},{"p":"Nêu điều mình muốn người khác làm: Would rather cộng chủ ngữ cộng quá khứ đơn khi có hai chủ ngữ khác nhau. (I'd rather you didn't smoke here.)"},{"p":"Ghi nhớ: It's time và would rather khi có chủ ngữ thứ hai thì mệnh đề theo sau dùng quá khứ đơn."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: It's time + S + quá khứ đơn | would rather + S + quá khứ đơn"},{"table":[["Cấu trúc","Công thức / Quy tắc","Ví dụ"],["It's time + to-V","không nêu chủ ngữ cụ thể","It's time to go."],["It's time + S + quá khứ đơn","nêu rõ ai nên làm, mang sắc thái phê bình","It's time you went home."],["would rather + V","một chủ ngữ, động từ nguyên mẫu không to","I'd rather walk."],["would rather + S + quá khứ đơn","hai chủ ngữ khác nhau","I'd rather you called later."],["would rather: ba dạng","would rather + V (not + V để phủ định) /would rather A than B / would rather + S + quá khứ (had/did)","would rather not disclose / rather delay than risk an error / would rather they had consulted a statistician"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xét sự có mặt của chủ ngữ thứ hai: Không có thì dùng to-V hoặc động từ nguyên mẫu; có thì dùng quá khứ đơn. (It's time to leave ↔ It's time we left)"},{"p":"02. Dùng quá khứ đơn cho tính giả định: Quá khứ đơn ở đây không chỉ thời gian quá khứ. (It's time he studied harder.)"},{"p":"03. Dùng were trong cấu trúc giả định: Dạng were là chuẩn mực, giống như trong câu điều kiện loại 2. (I'd rather he were more careful.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["It's time với chủ ngữ","It's time we left for the airport.\n(Đã đến lúc chúng ta phải đi sân bay.)","Quá khứ đơn left đánh dấu tính giả định, không chỉ thời gian quá khứ."],["It's time với to-V","It's time to review the whole plan.\n(Đã đến lúc xem lại toàn bộ kế hoạch.)","Khi không nêu ai thực hiện thì dùng to-V."],["Nhấn mạnh chậm trễ","It's high time she apologised for what she said.\n(Đã quá muộn để cô ấy phải xin lỗi về điều đã nói.)","It's high time làm sắc thái phê bình rõ hơn hẳn."],["Would rather một chủ ngữ","I'd rather stay at home tonight.\n(Tối nay tôi muốn ở nhà hơn.)","Chỉ có một chủ ngữ nên dùng động từ nguyên mẫu không to."],["Would rather hai chủ ngữ","I'd rather you didn't mention this to anyone.\n(Tôi muốn bạn đừng nhắc chuyện này với ai.)","Hai chủ ngữ khác nhau nên mệnh đề thứ hai dùng quá khứ đơn."],["Would rather với were","I'd rather he were more careful with the figures.\n(Tôi mong anh ấy cẩn thận hơn với số liệu.)","Động từ be ở dạng were trong cấu trúc giả định."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Chọn dạng theo số chủ ngữ"},{"table":[["Cấu trúc","Quy tắc","Ví dụ"],["It's time to-V","không nêu người thực hiện","It's time to start."],["It's time + S + quá khứ đơn","nêu người thực hiện, có phê bình nhẹ","It's time you started."],["would rather + V","một chủ ngữ","I'd rather go alone."],["would rather + S + quá khứ đơn","hai chủ ngữ","I'd rather you went alone."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: It's time we leave for the airport. → Đã sửa: It's time we left for the airport. — Khi có chủ ngữ thứ hai thì mệnh đề dùng quá khứ đơn."},{"p":"Chưa đúng: I'd rather you don't mention this. → Đã sửa: I'd rather you didn't mention this. — Hai chủ ngữ khác nhau thì mệnh đề thứ hai dùng quá khứ đơn."},{"p":"Chưa đúng: I'd rather to stay at home. → Đã sửa: I'd rather stay at home. — Would rather đi với động từ nguyên mẫu không to khi chỉ có một chủ ngữ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Câu có nêu chủ ngữ thứ hai hay không."},{"p":"Mệnh đề sau dùng quá khứ đơn khi có chủ ngữ thứ hai."},{"p":"Would rather đi với động từ nguyên mẫu không to khi chỉ có một chủ ngữ."},{"p":"Động từ be ở dạng were trong cấu trúc giả định."}]}],"id":"c1-15"},{"n":16,"title":"Impersonal & perception passives","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Bị động vô nhân xưng cho phép nêu một thông tin được nhiều người tin hoặc nói mà không phải chỉ rõ ai nói. Có hai cách diễn đạt song song: dạng với chủ ngữ hình thức it cộng mệnh đề that, và dạng đưa chủ ngữ thật lên đầu rồi dùng to-V. Nếu thông tin thuộc quá khứ thì dùng to have cộng quá khứ phân từ."},{"p":"Cấu trúc chính: It is said that … | S is said to + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): It is believed that the temple dates from the 15th century. (Nêu thông tin chưa xác nhận | Giữ giọng khách quan trong văn học thuật | Đưa chủ thể của thông tin lên đầu câu)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu thông tin chưa xác nhận: Dùng trong báo chí, nghiên cứu và văn bản hành chính. (It is reported that talks have resumed.)"},{"p":"Giữ giọng khách quan trong văn học thuật: Tránh phải nêu chủ thể của nhận định. (It is widely believed that the practice began here.)"},{"p":"Đưa chủ thể của thông tin lên đầu câu: Dạng S is said to đặt trọng tâm vào đối tượng được nói đến. (The painting is thought to be a forgery.)"},{"p":"Nêu thông tin về quá khứ: Dùng to have cộng quá khứ phân từ khi sự việc đã xảy ra trước đó. (He is believed to have left the country.)"},{"p":"Ghi nhớ: It is said that … và S is said to … dùng để nêu thông tin khách quan mà không chỉ rõ nguồn."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: It is said that … | S is said to + V"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Dạng với it","It is said / believed / thought / reported /known that + mệnh đề","It is said that she speaks five languages."],["Dạng với chủ ngữ thật","S + is said / believed / thought + to-V","She is said to speak five languages."],["Thông tin thuộc quá khứ","S + is said + to have + V3","He is said to have escaped."],["Bị động với động từ tri giác","S + was seen/heard + to-V hoặc V-ing","He was seen to enter the building. /He was heard shouting."],["Bị động tiếp diễn","am/is/are being + V3 = đang được làm","The protocol is being revised after the pilot study."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn dạng theo trọng tâm thông tin: Muốn nhấn vào cả mệnh đề thì dùng it; muốn nhấn vào đối tượng thì đưa nó lên đầu. (It is said that he is rich. ↔ He is said to be rich.)"},{"p":"02. Chuyển đúng dạng động từ khi đổi cấu trúc: Mệnh đề that ở hiện tại thì thành to-V; ở quá khứ thì thành to have cộng quá khứ phân từ. (that he left → to have left)"},{"p":"03. Nhớ đặc điểm của động từ tri giác: Ở chủ động, see và hear đi với động từ nguyên mẫu không to; ở bị động phải thêm to. (I saw him leave. → He was seen to leave.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Dạng với it","It is believed that the temple dates from the fifteenth century.\n(Người ta cho rằng ngôi đền có từ thế kỉ mười lăm.)","Chủ ngữ hình thức it mở đầu, sau đó là mệnh đề that hoàn chỉnh."],["Dạng với chủ ngữ thật","The temple is believed to date from the fifteenth century.\n(Ngôi đền được cho là có từ thế kỉ mười lăm.)","Cùng nội dung nhưng trọng tâm chuyển sang ngôi đền; mệnh đề that trở thành to-V."],["Thông tin thuộc quá khứ","He is believed to have left the country last week.\n(Người ta tin rằng anh ta đã rời khỏi nước tuần trước.)","Sự việc xảy ra trước thời điểm nhận định nên dùng to have cộng quá khứ phân từ."],["Trong báo chí","It is reported that talks between the two sides have resumed.\n(Có tin rằng các cuộc đàm phán giữa hai bên đã được nối lại.)","Cách diễn đạt này cho phép đưa tin mà không phải nêu nguồn cụ thể."],["Động từ tri giác bị động với to","He was seen to enter the building shortly before midnight.\n(Người ta thấy anh ta vào toà nhà ngay trước nửa đêm.)","Ở dạng chủ động là saw him enter, nhưng ở bị động phải thêm to."],["Động từ tri giác bị động với V-ing","She was heard shouting at someone on the phone.\n(Người ta nghe thấy cô ấy đang quát ai đó qua điện thoại.)","Dạng V-ing nhấn mạnh hành động đang diễn ra khi được nghe thấy."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai cách diễn đạt song song"},{"table":[["Cấu trúc","Trọng tâm","Ví dụ"],["It is said that + mệnh đề","nhấn vào toàn bộ nội dung","It is said that she is retiring."],["S is said to-V","nhấn vào đối tượng","She is said to be retiring."],["S is said to have + V3","nội dung thuộc quá khứ","She is said to have retired."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: It is believed the temple to date from the 15th century. → Đã sửa: It is believed that the temple dates from the 15th century. — Dạng với it phải đi kèm mệnh đề that, không đi với to-V."},{"p":"Chưa đúng: He is believed to left the country. → Đã sửa: He is believed to have left the country. — Thông tin thuộc quá khứ cần to have cộng quá khứ phân từ."},{"p":"Chưa đúng: He was seen enter the building. → Đã sửa: He was seen to enter the building. — Ở dạng bị động, động từ tri giác đòi hỏi to trước động từ nguyên mẫu."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Dạng với it luôn đi kèm mệnh đề that."},{"p":"Dạng với chủ ngữ thật dùng to-V hoặc to have cộng quá khứ phân từ."},{"p":"Thông tin thuộc quá khứ được thể hiện bằng to have cộng quá khứ phân từ."},{"p":"Động từ tri giác ở dạng bị động có thêm to."}]}],"id":"c1-16"},{"n":17,"title":"Complex noun phrases","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Văn học thuật nén thông tin chủ yếu bằng danh ngữ chứ không bằng cách thêm mệnh đề. Một danh ngữ phức gồm danh từ chính cùng các thành phần bổ nghĩa đứng trước và đứng sau nó. Nắm được trật tự này giúp người viết gộp nhiều ý vào một chủ ngữ mạch lạc, và giúp người đọc nhận ra danh từ chính để xác định động từ hòa hợp với nó."},{"p":"Cấu trúc chính: từ hạn định + bổ nghĩa trước + danh từ chính + bổ nghĩa sau"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The recently published report on rural schooling in Vietnam has attracted wide attention. (Gộp nhiều đặc điểm vào một chủ ngữ | Thêm thông tin sau danh từ chính | Xác định động từ hòa hợp)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Gộp nhiều đặc điểm vào một chủ ngữ: Bổ nghĩa trước gồm từ hạn định, tính từ, phân từ và danh từ bổ nghĩa. (a recently published government report)"},{"p":"Thêm thông tin sau danh từ chính: Bổ nghĩa sau gồm cụm giới từ, mệnh đề quan hệ rút gọn và mệnh đề đầy đủ. (the report on rural schooling published last year)"},{"p":"Xác định động từ hòa hợp: Động từ hòa hợp với danh từ chính, không với danh từ gần nó nhất. (The number of students is rising.)"},{"p":"Tránh câu dài bằng cách nén thành danh ngữ: Thay một mệnh đề bằng một danh ngữ giúp câu gọn và giữ mạch thông tin. (the failure of the system → nén từ the system failed)"},{"p":"Ghi nhớ: Nén nhiều tầng thông tin vào một danh ngữ bằng cách thêm thành phần bổ nghĩa trước và sau danh từ chính."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: từ hạn định + bổ nghĩa trước + danh từ chính + bổ nghĩa sau"},{"table":[["Thành phần","Công thức","Ví dụ"],["Bổ nghĩa trước","từ hạn định + trạng từ + tính từ hoặc phân từ + danh từ bổ nghĩa","these two highly effective teaching methods"],["Cụm giới từ","danh từ chính + of/on/in/for + cụm danh từ","the impact of climate change on agriculture"],["Mệnh đề rút gọn","danh từ chính + V-ing hoặc V3","the students taking the exam / the data collected in 2020"],["Mệnh đề đầy đủ","danh từ chính + that hoặc which + mệnh đề","the assumption that growth continues"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định danh từ chính: Danh từ chính quyết định động từ hòa hợp và là trung tâm nghĩa của cả cụm. (the number of students → number)"},{"p":"02. Xếp bổ nghĩa trước theo trật tự quy ước: Từ hạn định, rồi trạng từ và tính từ, rồi danh từ bổ nghĩa sát danh từ chính. (the three main research findings)"},{"p":"03. Thêm bổ nghĩa sau theo mức độ chi tiết: Cụm giới từ trước, rồi mệnh đề rút gọn, rồi mệnh đề đầy đủ. (the report on schooling published last year)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Danh ngữ phức làm chủ ngữ","The recently published report on rural schooling in Vietnam has attracted wide attention.\n(Báo cáo mới công bố về giáo dục ở nông thôn Việt Nam đã thu hút nhiều quan tâm.)","Danh từ chính là report; trước nó là bổ nghĩa recently published, sau nó là hai cụm giới từ."],["Hòa hợp với danh từ chính","The number of students applying for scholarships is rising.\n(Số sinh viên xin học bổng đang tăng.)","Danh từ chính là number ở số ít nên động từ là is, không phải are theo students."],["Bổ nghĩa trước nhiều tầng","These two highly effective teaching methods were introduced last term.\n(Hai phương pháp dạy rất hiệu quả này được áp dụng từ học kì trước.)","Trật tự là từ hạn định, số từ, trạng từ, tính từ, rồi danh từ bổ nghĩa teaching."],["Mệnh đề rút gọn","The data collected in 2020 differ from the figures reported earlier.\n(Dữ liệu thu thập năm 2020 khác với các số liệu công bố trước đó.)","Hai cụm rút gọn mang nghĩa bị động nên dùng quá khứ phân từ."],["Mệnh đề đầy đủ bổ nghĩa","The assumption that growth will continue indefinitely is questionable.\n(Giả định rằng tăng trưởng sẽ tiếp tục vô hạn là điều đáng ngờ.)","Mệnh đề that bổ nghĩa cho assumption và động từ is hòa hợp với assumption."],["Nén mệnh đề thành danh ngữ","The failure of the cooling system caused the shutdown.\n(Việc hệ thống làm mát hỏng đã gây ra sự cố ngừng hoạt động.)","Mệnh đề the cooling system failed được nén thành danh ngữ để làm chủ ngữ."],["Hoà hợp theo danh từ chính","The implications of this finding for future policy have been overstated.\n(Những hệ quả của phát hiện này đối với chính sách về sau đã bị thổi phồng.)","Danh từ chính là implications (số nhiều) nên động từ là have, dù policy số ít đứng sát ngay trước."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Vị trí của các loại bổ nghĩa"},{"table":[["Loại bổ nghĩa","Vị trí & Thành phần","Ví dụ"],["bổ nghĩa trước","từ hạn định, tính từ, phân từ đơn, danh từ bổ nghĩa","a published report"],["cụm giới từ","ngay sau danh từ chính","a report on schooling"],["mệnh đề rút gọn","sau cụm giới từ","a report published last year"],["mệnh đề đầy đủ","sau cùng","a report that nobody has read"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The report has attracted wide attention which was published recently. → Đã sửa: The recently published report has attracted wide attention. — Mệnh đề quan hệ bị tách xa danh từ nó bổ nghĩa; nén thành bổ nghĩa trước sẽ rõ hơn."},{"p":"Chưa đúng: The number of students are rising. → Đã sửa: The number of students is rising. — Động từ hòa hợp với danh từ chính number, không với students."},{"p":"Chưa đúng: The collected data in 2020 differ from earlier figures. → Đã sửa: The data collected in 2020 differ from earlier figures. — Cụm rút gọn có bổ ngữ riêng thì phải đứng sau danh từ chính."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Danh từ chính của cụm đã được xác định."},{"p":"Động từ hòa hợp với danh từ chính."},{"p":"Bổ nghĩa trước xếp theo trật tự quy ước."},{"p":"Bổ nghĩa sau đứng ngay cạnh danh từ nó bổ nghĩa."},{"p":"Động từ hoà hợp với danh từ chính của cả cụm, không phải danh từ đứng gần nhất: The implications … have been overstated."}]}],"id":"c1-17"},{"n":18,"title":"Nominalisation","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Danh hoá là chuyển một hành động hoặc một đặc điểm thành danh từ, nhờ đó câu nén được nhiều thông tin và mang giọng khách quan hơn. Đây là nét đặc trưng của văn phong học thuật. Tuy nhiên nếu lạm dụng, câu sẽ nặng và khó đọc, nên cần cân bằng giữa dạng danh từ và dạng động từ."},{"p":"Cấu trúc chính: decide → decision | effective → effectiveness"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The decision to postpone the launch surprised everyone. (Nén một mệnh đề thành cụm danh từ | Tạo giọng khách quan | Làm chủ ngữ cho câu học thuật)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nén một mệnh đề thành cụm danh từ: Nhờ vậy câu có thể nối thêm thông tin mà không cần thêm mệnh đề. (They decided to postpone it. → The decision to postpone it…)"},{"p":"Tạo giọng khách quan: Danh hoá cho phép bỏ chủ thể của hành động. (the implementation of the policy)"},{"p":"Làm chủ ngữ cho câu học thuật: Cụm danh hoá thường làm chủ ngữ và kéo theo động từ số ít. (The analysis of the data took three months.)"},{"p":"Liên kết câu bằng cách nhắc lại ý trước: Dùng cụm danh hoá để tóm lại ý vừa nêu. (Prices rose sharply. This increase worried investors.)"},{"p":"Ghi nhớ: Chuyển động từ hoặc tính từ thành danh từ để nén thông tin và tạo giọng khách quan."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: decide → decision | effective → effectiveness"},{"table":[["Nhóm hậu tố / Cấu trúc","Ví dụ biến đổi","Cụm danh hoá"],["-tion / -sion","decide → decision, implement → implementation","the implementation of the plan"],["-ment / -al","develop → development, arrive → arrival","the development of new methods"],["-ness / -ity / -ance","effective → effectiveness, able → ability, perform → performance","the effectiveness of the treatment"],["Cấu trúc đi kèm","the + danh từ + of + đối tượng / the + danh từ + to-V","the failure to respond"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn hậu tố đúng cho từ gốc: Không có quy tắc duy nhất nên cần tra và nhớ theo từ. (analyse → analysis / comply → compliance)"},{"p":"02. Nối với đối tượng bằng of: Cấu trúc phổ biến nhất là the cộng danh từ cộng of cộng cụm danh từ. (the analysis of the results)"},{"p":"03. Kiểm tra độ nặng của câu: Nếu một câu có quá nhiều cụm danh hoá thì nên chuyển một vài cụm về dạng động từ. (the carrying out of an investigation → investigating)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Danh hoá động từ","The decision to postpone the launch surprised everyone.\n(Quyết định hoãn ra mắt làm mọi người bất ngờ.)","Decide thành decision; cụm danh hoá làm chủ ngữ và đi với động từ số ít."],["Danh hoá tính từ","The effectiveness of the treatment has not yet been proven.\n(Hiệu quả của phương pháp điều trị vẫn chưa được chứng minh.)","Effective thành effectiveness, nối với đối tượng bằng of."],["Nén mệnh đề","The failure to respond within a week led to the complaint.\n(Việc không phản hồi trong vòng một tuần đã dẫn tới đơn khiếu nại.)","Mệnh đề they did not respond được nén thành cụm the failure to respond."],["Giọng khách quan","The implementation of the new policy begins in July.\n(Việc triển khai chính sách mới bắt đầu từ tháng Bảy.)","Không cần nêu ai triển khai, nhờ đó câu mang giọng khách quan."],["Liên kết câu","Prices rose sharply last quarter. This increase worried investors.\n(Giá tăng mạnh trong quý trước. Mức tăng này làm các nhà đầu tư lo ngại.)","Cụm this increase nhắc lại ý ở câu trước, tạo mạch liên kết."],["Danh hoá vừa phải","Instead of the carrying out of an investigation, the team simply investigated.\n(Thay vì việc tiến hành một cuộc điều tra, nhóm chỉ đơn giản là điều tra.)","Ví dụ cho thấy danh hoá quá mức làm câu nặng, nên dùng động từ sẽ gọn hơn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Dạng động từ và dạng danh hoá"},{"table":[["Cách diễn đạt","Đặc điểm","Văn phong"],["They decided quickly.","dạng động từ, gọn và dễ đọc","giọng trung tính"],["Their decision was quick.","dạng danh hoá, khách quan hơn","giọng học thuật"],["The quickness of their decision-making","danh hoá quá mức, câu trở nên nặng","nên tránh"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The decide to postpone the launch surprised everyone. → Đã sửa: The decision to postpone the launch surprised everyone. — Vị trí chủ ngữ cần danh từ, không dùng động từ."},{"p":"Chưa đúng: The analysis of the data were completed in May. → Đã sửa: The analysis of the data was completed in May. — Danh từ chính là analysis ở số ít nên động từ phải là was."},{"p":"Chưa đúng: The effectivity of the treatment is unproven. → Đã sửa: The effectiveness of the treatment is unproven. — Dạng danh hoá chuẩn mực của effective là effectiveness."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Hậu tố danh hoá đã đúng với từ gốc."},{"p":"Cụm danh hoá nối với đối tượng bằng of hoặc to-V."},{"p":"Động từ hòa hợp với danh từ chính của cụm."},{"p":"Mật độ danh hoá trong câu không làm câu nặng."}]}],"id":"c1-18"},{"n":19,"title":"Ellipsis & substitution","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Khi một phần thông tin đã rõ với người đọc, tiếng Anh cho phép lược bỏ nó hoặc thay bằng một từ ngắn. Phép lược bỏ hẳn phần trùng lặp, thường giữ lại trợ động từ. Phép thế dùng một từ như one, so, do, that để đứng thay. Hai kĩ thuật này làm văn bản gọn và mạch liên kết chặt hơn."},{"p":"Cấu trúc chính: I think so | the red one | so do I"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I haven't finished the report, but Nam has. (Lược bỏ phần sau trợ động từ | Thay danh từ bằng one hoặc ones | Thay mệnh đề bằng so hoặc not)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Lược bỏ phần sau trợ động từ: Giữ lại trợ động từ, lược phần còn lại của vị ngữ. (She can swim, but I can't.)"},{"p":"Thay danh từ bằng one hoặc ones: One thay cho danh từ đếm được số ít, ones cho số nhiều. (I'll take the blue one.)"},{"p":"Thay mệnh đề bằng so hoặc not: Dùng sau think, hope, believe, be afraid. (Is it raining? - I think so. / I hope not.)"},{"p":"Hưởng ứng bằng so và neither: So do I cho ý khẳng định, neither do I cho ý phủ định. (I like jazz. - So do I.)"},{"p":"Ghi nhớ: Lược bỏ hoặc thay thế phần đã nhắc để tránh lặp mà vẫn giữ nghĩa rõ ràng."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: I think so | the red one | so do I"},{"table":[["Kĩ thuật","Công thức / Quy tắc","Ví dụ"],["Phép lược","giữ trợ động từ, lược phần sau","He hasn't eaten, but she has."],["one / ones","thay danh từ đếm được","the big one / the red ones"],["so / not","thay cả mệnh đề sau think, hope, believe","I'm afraid so. / I hope not."],["so / neither đảo ngữ","So + trợ động từ + S / Neither + trợ động từ + S","So am I. / Neither have I."],["did too · so did","vế sau rút gọn bằng trợ động từ: S + did too/ so did + S","The 2016 survey covered four provinces; the 2019 one did too."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định phần đã rõ với người đọc: Chỉ lược được phần mà người đọc chắc chắn suy ra được. (I haven't finished, but Nam has.)"},{"p":"02. Giữ lại trợ động từ khi lược vị ngữ: Trợ động từ là chỗ neo để người đọc hiểu phần bị lược. (She will, but he won't.)"},{"p":"03. Chọn từ thay đúng thành phần: Danh từ đếm được dùng one, mệnh đề dùng so, vị ngữ dùng do. (the red one / I think so / She does too.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Lược vị ngữ","I haven't finished the report, but Nam has.\n(Tôi chưa làm xong báo cáo, nhưng Nam thì xong rồi.)","Phần finished the report được lược vì người đọc đã biết, chỉ giữ lại trợ động từ has."],["Thay bằng one","These shoes are too small - I'll take the bigger ones.\n(Đôi này nhỏ quá, tôi lấy đôi lớn hơn.)","Ones thay cho shoes ở số nhiều để tránh lặp danh từ."],["Thay mệnh đề bằng so","Is the museum open today? - I think so.\n(Hôm nay bảo tàng mở không? - Tôi nghĩ là có.)","So thay cho cả mệnh đề the museum is open today."],["Dùng not","Will it rain tomorrow? - I hope not.\n(Mai có mưa không? - Tôi mong là không.)","I hope not là dạng phủ định chuẩn mực, không nói I don't hope so."],["Hưởng ứng khẳng định","I love this piece of music. - So do I.\n(Tôi rất thích bản nhạc này. - Tôi cũng vậy.)","So do I đảo trợ động từ lên trước chủ ngữ và phải khớp với động từ của câu trước."],["Hưởng ứng phủ định","I haven't seen that film. - Neither have I.\n(Tôi chưa xem bộ phim đó. - Tôi cũng chưa.)","Neither dùng để hưởng ứng ý phủ định và cũng đảo trợ động từ."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba công cụ tránh lặp"},{"table":[["Công cụ","Quy tắc","Ví dụ"],["phép lược","bỏ hẳn phần trùng, giữ trợ động từ","She will, but I won't."],["one / ones","thay danh từ đếm được","I prefer the smaller one."],["so / do","thay mệnh đề hoặc vị ngữ","I believe so. / He does too."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I haven't finished the report, but Nam has finished the report. → Đã sửa: I haven't finished the report, but Nam has. — Phần trùng lặp nên được lược để câu gọn và mạch liên kết chặt hơn."},{"p":"Chưa đúng: I don't hope so. → Đã sửa: I hope not. — Với hope, dạng phủ định chuẩn mực là hope not."},{"p":"Chưa đúng: I like jazz. - So I do. → Đã sửa: I like jazz. - So do I. — Hưởng ứng bằng so đòi hỏi đảo trợ động từ lên trước chủ ngữ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Phần bị lược là phần người đọc suy ra được."},{"p":"Trợ động từ được giữ lại làm chỗ neo."},{"p":"Từ thay phù hợp với thành phần bị thay."},{"p":"Cấu trúc hưởng ứng có đảo trợ động từ."}]}],"id":"c1-19"},{"n":20,"title":"Punctuation in complex sentences","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ở trình độ C1, dấu câu là công cụ thể hiện quan hệ logic chứ không còn là chuyện hình thức. Dấu phẩy không nối được hai mệnh đề độc lập nếu không có liên từ và đây là lỗi nặng trong văn học thuật. Dấu chấm phẩy nối hai mệnh đề ngang hàng. Dấu hai chấm mở ra phần làm rõ hoặc liệt kê. Dấu gạch ngang chèn thông tin phụ với giọng nhấn hơn dấu phẩy."},{"p":"Cấu trúc chính: mệnh đề; mệnh đề | mệnh đề: phần làm rõ | câu - phần chèn - câu"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The method worked; however, it was expensive. (Nối hai mệnh đề độc lập | Dùng với trạng ngữ liên kết | Giới thiệu phần làm rõ hoặc liệt kê)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nối hai mệnh đề độc lập: Dùng dấu chấm phẩy hoặc dấu phẩy kèm một liên từ như and, but, so. (The test failed; the cause was unclear.)"},{"p":"Dùng với trạng ngữ liên kết: However, therefore, nevertheless cần dấu chấm phẩy hoặc dấu chấm ở trước. (It rained; therefore, we postponed it.)"},{"p":"Giới thiệu phần làm rõ hoặc liệt kê: Dấu hai chấm đặt sau một mệnh đề hoàn chỉnh. (The result was clear: the drug had no effect.)"},{"p":"Chèn thông tin phụ: Dấu gạch ngang hoặc dấu ngoặc đơn chèn thông tin bổ sung. (The samples - all collected in May - were contaminated.)"},{"p":"Ghi nhớ: Dấu chấm phẩy nối hai mệnh đề độc lập, dấu hai chấm giới thiệu phần làm rõ, dấu gạch ngang chèn thông tin phụ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: mệnh đề; mệnh đề | mệnh đề: phần làm rõ | câu - phần chèn - câu"},{"table":[["Dấu câu","Công thức / Quy tắc","Ví dụ"],["Dấu chấm phẩy","mệnh đề độc lập; mệnh đề độc lập","She left early; he stayed."],["Dấu phẩy với liên từ","mệnh đề, and/but/so + mệnh đề","She left early, but he stayed."],["Dấu hai chấm","mệnh đề hoàn chỉnh: phần làm rõ hoặc danh sách","Three factors matter: cost, time and access."],["Dấu gạch ngang và ngoặc đơn","câu - phần chèn - câu / câu (phần chèn) câu","The data (n = 240) were reliable."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xét tính độc lập của hai mệnh đề: Nếu cả hai đều đứng riêng thành câu được thì dấu phẩy một mình là chưa đủ. (The test failed; the cause was unclear.)"},{"p":"02. Chọn dấu theo quan hệ logic: Ngang hàng thì dùng dấu chấm phẩy; làm rõ thì dùng dấu hai chấm; bổ sung thì dùng dấu gạch ngang. (…: the drug had no effect.)"},{"p":"03. Kiểm tra phần trước dấu hai chấm: Phần đứng trước dấu hai chấm phải là một mệnh đề hoàn chỉnh. (sai: The factors are: cost and time.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Trạng ngữ liên kết","The method worked; however, it was expensive.\n(Phương pháp có hiệu quả; tuy vậy, nó tốn kém.)","However cần dấu chấm phẩy ở trước và dấu phẩy ở sau; dùng dấu phẩy cả hai bên là lỗi nối câu."],["Hai mệnh đề ngang hàng","The first test failed; the second produced clear results.\n(Lần thử đầu thất bại; lần thứ hai cho kết quả rõ ràng.)","Dấu chấm phẩy nối hai mệnh đề độc lập mà không cần liên từ."],["Dấu phẩy với liên từ","The first test failed, but the second produced clear results.\n(Lần thử đầu thất bại, nhưng lần thứ hai cho kết quả rõ ràng.)","Khi có liên từ but thì dấu phẩy là đủ."],["Dấu hai chấm làm rõ","The result was unambiguous: the drug had no measurable effect.\n(Kết quả rõ ràng: thuốc không có tác dụng đo được.)","Phần trước dấu hai chấm là một mệnh đề hoàn chỉnh, phần sau làm rõ nó."],["Dấu hai chấm liệt kê","Three factors matter most: cost, time and accessibility.\n(Ba yếu tố quan trọng nhất là chi phí, thời gian và khả năng tiếp cận.)","Dấu hai chấm mở ra danh sách sau một mệnh đề hoàn chỉnh."],["Dấu gạch ngang chèn thông tin","The samples - all collected in May -were contaminated.\n(Các mẫu, tất cả đều lấy vào tháng Năm, đều bị nhiễm.)","Dấu gạch ngang chèn thông tin phụ với giọng nhấn hơn dấu phẩy."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Bốn dấu và bốn quan hệ"},{"table":[["Dấu câu","Quan hệ logic","Ví dụ"],["dấu phẩy + liên từ","nối hai mệnh đề có liên từ","It rained, so we left."],["dấu chấm phẩy","nối hai mệnh đề ngang hàng, không cần liên từ","It rained; we left."],["dấu hai chấm","giới thiệu phần làm rõ hoặc liệt kê","One thing was clear: it rained."],["dấu gạch ngang","chèn thông tin phụ có nhấn","It rained - heavily - all night."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The method worked, however, it was expensive. → Đã sửa: The method worked; however, it was expensive. — Dấu phẩy một mình không nối được hai mệnh đề độc lập; đây là lỗi nối câu."},{"p":"Chưa đúng: The factors are: cost, time and access. → Đã sửa: Three factors matter: cost, time and access. — Phần trước dấu hai chấm phải là một mệnh đề hoàn chỉnh, không kết thúc bằng động từ đang chờ bổ ngữ."},{"p":"Chưa đúng: The test failed, the cause was unclear. → Đã sửa: The test failed; the cause was unclear. — Hai mệnh đề độc lập cần dấu chấm phẩy hoặc một liên từ."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Hai phần được nối có phải mệnh đề độc lập hay không."},{"p":"Trạng ngữ liên kết có dấu chấm phẩy hoặc dấu chấm ở trước."},{"p":"Phần trước dấu hai chấm là một mệnh đề hoàn chỉnh."},{"p":"Dấu gạch ngang dùng theo cặp khi chèn giữa câu."}]}],"id":"c1-20"},{"n":21,"title":"Advanced linkers","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ở trình độ cao, người viết cần phân biệt ba nhóm từ nối vì chúng khác nhau về dấu câu và vị trí. Liên từ như but và although nối hai mệnh đề trong một câu. Trạng ngữ liên kết như however và nevertheless nối hai câu và cần dấu chấm hoặc dấu chấm phẩy ở phía trước. Giới từ như despite và in spite of đi với danh từ hoặc V-ing."},{"p":"Cấu trúc chính: mệnh đề; nevertheless, mệnh đề"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The method is expensive; nevertheless, it remains the most reliable. (Nêu tương phản mạnh giữa hai câu | So sánh hai vế đối lập trong một câu | Nêu kết luận hoặc hệ quả)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu tương phản mạnh giữa hai câu: However, nevertheless, nonetheless đứng đầu câu thứ hai và có dấu phẩy theo sau. (…; nevertheless, the results hold.)"},{"p":"So sánh hai vế đối lập trong một câu: Whereas và while nối hai mệnh đề đối lập trực tiếp. (Group A improved, whereas Group B did not.)"},{"p":"Nêu kết luận hoặc hệ quả: Therefore, hence, thus, consequently dẫn vào kết quả logic. (The sample was small; hence, the findings are tentative.)"},{"p":"Bổ sung thông tin cùng hướng: Moreover, furthermore, in addition thêm một luận điểm nữa. (Moreover, the cost fell by half.)"},{"p":"Ghi nhớ: Nevertheless, whereas, hence, moreover nối ý ở cấp độ câu và đoạn với dấu câu riêng."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: mệnh đề; nevertheless, mệnh đề"},{"table":[["Nhóm từ nối","Từ / Quy tắc","Ví dụ"],["Liên từ","and, but, although, whereas, while - nối trong một câu","Although it rained, we went."],["Trạng ngữ liên kết","however, nevertheless, therefore, moreover\n- cần dấu chấm hoặc dấu chấm phẩy trước","It rained. However, we went."],["Giới từ","despite, in spite of, because of, owing to + danh từ hoặc V-ing","Despite the rain, we went."],["Cặp tương ứng","although ↔ despite / because ↔ because of / but ↔ however","because it rained ↔ because of the rain"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định quan hệ logic cần thể hiện: Tương phản, nguyên nhân, kết quả, bổ sung hay nhượng bộ. (tương phản → however, whereas)"},{"p":"02. Chọn nhóm từ nối theo cấu trúc câu: Nối hai mệnh đề thì dùng liên từ; nối hai câu thì dùng trạng ngữ liên kết; đi với danh từ thì dùng giới từ. (although + mệnh đề ↔ despite + danh từ)"},{"p":"03. Đặt dấu câu đúng: Trạng ngữ liên kết cần dấu chấm hoặc dấu chấm phẩy ở trước và dấu phẩy ở sau. (…; nevertheless, …)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Trạng ngữ liên kết","The method is expensive; nevertheless, it remains the most reliable.\n(Phương pháp này tốn kém; tuy vậy, nó vẫn đáng tin cậy nhất.)","Nevertheless cần dấu chấm phẩy ở trước và dấu phẩy ở sau; dùng dấu phẩy ở cả hai đầu là lỗi."],["So sánh hai vế","Group A showed clear improvement, whereas Group B remained unchanged.\n(Nhóm A cải thiện rõ rệt, trong khi nhóm B không thay đổi.)","Whereas là liên từ nên nối được hai mệnh đề trong cùng một câu với dấu phẩy."],["Nêu hệ quả","The sample was very small; hence, the findings should be treated as tentative.\n(Mẫu rất nhỏ, do đó kết quả nên được xem là sơ bộ.)","Hence mang giọng học thuật, tương đương therefore nhưng ngắn gọn hơn."],["Bổ sung luận điểm","The new process is faster. Moreover, it uses less energy.\n(Quy trình mới nhanh hơn. Hơn nữa, nó tiêu thụ ít năng lượng hơn.)","Moreover mở đầu câu mới và có dấu phẩy theo sau."],["Giới từ nhượng bộ","Despite the heavy rain, the ceremony went ahead.\n(Dù mưa lớn, buổi lễ vẫn diễn ra.)","Despite đi với cụm danh từ, không đi với mệnh đề."],["Cặp tương ứng","Although it rained heavily, the ceremony went ahead; despite the rain, nobody left.\n(Dù mưa lớn, buổi lễ vẫn diễn ra; mặc dù mưa, không ai rời đi.)","Although đi với mệnh đề, despite đi với danh từ, hai cấu trúc không thay thế trực tiếp cho nhau."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba nhóm từ nối và cấu trúc đi kèm"},{"table":[["Từ nối","Loại từ & Quy tắc","Ví dụ"],["although / whereas","liên từ, đi với mệnh đề","Although he tried, he failed."],["however / nevertheless","trạng ngữ liên kết, nối hai câu","He tried. However, he failed."],["despite / in spite of","giới từ, đi với danh từ hoặc V-ing","Despite trying, he failed."],["therefore / hence / thus","trạng ngữ liên kết chỉ hệ quả","The data were thin; hence, caution is needed."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The method is expensive, nevertheless it remains the most reliable. → Đã sửa: The method is expensive; nevertheless, it remains the most reliable. — Trạng ngữ liên kết không nối được hai mệnh đề chỉ bằng dấu phẩy."},{"p":"Chưa đúng: Despite it rained heavily, the ceremony went ahead. → Đã sửa: Despite the heavy rain, the ceremony went ahead. — Despite đi với danh từ hoặc V-ing, không đi với mệnh đề."},{"p":"Chưa đúng: Although the delay, the flight landed on time. → Đã sửa: Despite the delay, the flight landed on time. — Although đòi hỏi một mệnh đề; với cụm danh từ thì dùng despite."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Quan hệ logic đã được xác định rõ."},{"p":"Nhóm từ nối phù hợp với cấu trúc câu."},{"p":"Dấu câu quanh trạng ngữ liên kết đã đúng."},{"p":"Despite và although không bị dùng lẫn."}]}],"id":"c1-21"}];
